6	// HansEncode AscendC kernel — exponent byte histogram (bincount over 256 bins)
7	// Supports float32 via AIC path, float16/bfloat16 via AIV scalar path
8	//
9	// Two kernel entry points:
10	//   1. hans_encode_compute — Each core builds local histogram, writes to workspace
11	//   2. hans_encode_reduce  — 1 core aggregates workspace rows -> output
12	
13	#include "kernel_operator.h"
14	
15	constexpr int32_t BUFFER_NUM = 2;
16	constexpr int32_t TILE_LEN = 2048;
17	constexpr int32_t HIST_SIZE = 256;
18	
19	// ---------------------------------------------------------------------------
20	// Helpers
21	// ---------------------------------------------------------------------------
22	
23	__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b)
24	{
25	    return (a + b - 1) / b;
26	}
27	
28	template <typename T>
29	__aicore__ inline void LoadGmToUbPad(
30	    AscendC::LocalTensor<T> &dst,
31	    const AscendC::GlobalTensor<T> &src,
32	    uint32_t count)
33	{
34	    AscendC::DataCopyExtParams copyParams = {
35	        1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPadExtParams<T> padParams = {true, 0, 0, static_cast<T>(0)};
37	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
38	}
39	
40	template <typename T>
41	__aicore__ inline void StoreUbToGmPad(
42	    const AscendC::GlobalTensor<T> &dst,
43	    const AscendC::LocalTensor<T> &src,
44	    uint32_t count)
45	{
46	    AscendC::DataCopyExtParams copyParams = {
47	        1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
48	    AscendC::DataCopyPad(dst, src, copyParams);
49	}
50	
51	// ---------------------------------------------------------------------------
52	// KernelHansEncodeCompute — Per-core histogram builder
53	// ---------------------------------------------------------------------------
54	template <typename T>
55	class KernelHansEncodeCompute {
56	public:
57	    __aicore__ inline void Init(
58	        GM_ADDR inputGM,
59	        GM_ADDR workspaceGM,
60	        int32_t totalElems,
61	        int32_t numCores,
62	        int32_t elemsPerCore,
63	        int32_t shiftBits)
64	    {
65	        totalElems_ = static_cast<uint32_t>(totalElems);
66	        numCores_ = numCores;
67	        elemsPerCore_ = elemsPerCore;
68	        shiftBits_ = shiftBits;
69	
70	        coreIdx_ = static_cast<uint32_t>(AscendC::GetBlockIdx());
71	        base_ = coreIdx_ * static_cast<uint32_t>(elemsPerCore_);
72	        localElems_ = totalElems_ - base_;
73	        if (localElems_ > static_cast<uint32_t>(elemsPerCore_)) {
74	            localElems_ = static_cast<uint32_t>(elemsPerCore_);
75	        }
76	        numTiles_ = CeilDiv(localElems_, TILE_LEN);
77	
78	        inputGlobal_.SetGlobalBuffer(
79	            reinterpret_cast<__gm__ T*>(inputGM) + base_,
80	            static_cast<uint64_t>(elemsPerCore_));
81	        wsGlobal_.SetGlobalBuffer(
82	            reinterpret_cast<__gm__ int32_t*>(workspaceGM) +
83	                static_cast<uint64_t>(coreIdx_) * static_cast<uint64_t>(HIST_SIZE),
84	            HIST_SIZE);
85	
86	        pipe_.InitBuffer(inQueue_, BUFFER_NUM, TILE_LEN * sizeof(T));
87	
88	        // In-init VECCALC buffers for uint8 byte extraction and histogram
89	        pipe_.InitBuffer(byteBuf_, TILE_LEN * sizeof(uint8_t));
90	        pipe_.InitBuffer(histBuf_, HIST_SIZE * sizeof(int32_t));
91	
92	        // AIC-only: integer vector buffers for bincount
93	        if ASCEND_IS_AIC {
94	            pipe_.InitBuffer(maskBuf_, TILE_LEN * sizeof(uint8_t));
95	            pipe_.InitBuffer(cntBuf_, TILE_LEN * sizeof(int32_t));
96	            pipe_.InitBuffer(onesBuf_, TILE_LEN * sizeof(int32_t));
97	            pipe_.InitBuffer(workBuf_, TILE_LEN * sizeof(int32_t));
98	            pipe_.InitBuffer(sumBuf_, sizeof(int32_t));
99	        }
100	    }
101	
102	    __aicore__ inline void Process()
103	    {
104	        auto histLocal = histBuf_.template Get<int32_t>();
105	        AscendC::Duplicate(histLocal, static_cast<int32_t>(0), HIST_SIZE);
106	
107	        for (uint32_t t = 0; t < numTiles_; ++t) {
108	            uint32_t curLen = TILE_LEN;
109	            if (t + 1 == numTiles_) {
110	                uint32_t remain = localElems_ - t * TILE_LEN;
111	                if (remain > 0 && remain < TILE_LEN) {
112	                    curLen = remain;
113	                }
114	            }
115	            CopyIn(t, curLen);
116	            Compute(curLen);
117	        }
118	
119	        StoreUbToGmPad<int32_t>(wsGlobal_, histLocal,
120	                                static_cast<uint32_t>(HIST_SIZE));
121	    }
122	
123	private:
124	    __aicore__ inline void CopyIn(uint32_t tileIdx, uint32_t curLen)
125	    {
126	        auto inLocal = inQueue_.AllocTensor<T>();
127	        auto srcGM = inputGlobal_[static_cast<uint64_t>(tileIdx) * TILE_LEN];
128	        LoadGmToUbPad<T>(inLocal, srcGM, curLen);
129	        inQueue_.EnQue(inLocal);
130	    }
131	
132	    __aicore__ inline void Compute(uint32_t curLen)
133	    {
134	        auto inLocal = inQueue_.DeQue<T>();
135	        auto histLocal = histBuf_.template Get<int32_t>();
136	        auto byteLocal = byteBuf_.template Get<uint8_t>();
137	
138	        // Step 1: Extract exponent byte from raw float bits (scalar for all paths)
139	        if constexpr (sizeof(T) == 4) {
140	            auto uint32View = inLocal.template ReinterpretCast<uint32_t>();
141	            for (uint32_t i = 0; i < curLen; ++i) {
142	                uint32_t bits = uint32View.GetValue(i);
143	                byteLocal.SetValue(i,
144	                    static_cast<uint8_t>(bits >> static_cast<uint32_t>(shiftBits_)));
145	            }
146	        } else {
147	            auto uint16View = inLocal.template ReinterpretCast<uint16_t>();
148	            for (uint32_t i = 0; i < curLen; ++i) {
149	                uint16_t bits = uint16View.GetValue(i);
150	                byteLocal.SetValue(i,
151	                    static_cast<uint8_t>(bits >> static_cast<uint16_t>(shiftBits_)));
152	            }
153	        }
154	        AscendC::PipeBarrier<PIPE_V>();
155	
156	        // Step 2: Bincount
157	        if ASCEND_IS_AIC {
158	            BincountAic(byteLocal, histLocal, curLen);
159	        }
160	        if ASCEND_IS_AIV {
161	            BincountAiv(byteLocal, histLocal, curLen);
162	        }
163	
164	        inQueue_.FreeTensor(inLocal);
165	    }
166	
167	    // ---- AIC: vectorized bincount (CompareScalar + Select + ReduceSum) ----
168	    __aicore__ inline void BincountAic(
169	        AscendC::LocalTensor<uint8_t> &byteLocal,
170	        AscendC::LocalTensor<int32_t> &histLocal,
171	        uint32_t curLen)
172	    {
173	        auto maskLocal = maskBuf_.template Get<uint8_t>();
174	        auto onesLocal = onesBuf_.template Get<int32_t>();
175	        AscendC::Duplicate(onesLocal, static_cast<int32_t>(1),
176	                           static_cast<int32_t>(curLen));
177	        auto cntLocal = cntBuf_.template Get<int32_t>();
178	        auto workLocal = workBuf_.template Get<int32_t>();
179	        auto cntSum = sumBuf_.template Get<int32_t>();
180	
181	        for (int32_t b = 0; b < HIST_SIZE; ++b) {
182	            AscendC::CompareScalar(maskLocal, byteLocal,
183	                                   static_cast<uint8_t>(b),
184	                                   AscendC::CMPMODE::EQ,
185	                                   static_cast<uint32_t>(curLen));
186	
187	            AscendC::Select(cntLocal, maskLocal, onesLocal,
188	                            static_cast<int32_t>(0),
189	                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE,
190	                            static_cast<uint32_t>(curLen));
191	
192	            AscendC::ReduceSum<int32_t>(cntSum, cntLocal, workLocal,
193	                                        static_cast<int32_t>(curLen));
194	            AscendC::PipeBarrier<PIPE_V>();
195	
196	            int32_t addVal = cntSum.GetValue(0);
197	            int32_t curVal = histLocal.GetValue(b);
198	            histLocal.SetValue(b, curVal + addVal);
199	        }
200	    }
201	
202	    // ---- AIV: scalar bincount (scalar comparison to avoid AIV type restrictions) ----
203	    __aicore__ inline void BincountAiv(
204	        AscendC::LocalTensor<uint8_t> &byteLocal,
205	        AscendC::LocalTensor<int32_t> &histLocal,
206	        uint32_t curLen)
207	    {
208	        // Pre-read all byte values into the byteLocal buffer (already filled)
209	        // For each bin [0,255], count matching elements in byteLocal
210	        for (int32_t b = 0; b < HIST_SIZE; ++b) {
211	            uint8_t binVal = static_cast<uint8_t>(b);
212	            int32_t count = 0;
213	            for (uint32_t i = 0; i < curLen; ++i) {
214	                if (byteLocal.GetValue(i) == binVal) {
215	                    count++;
216	                }
217	            }
218	            if (count > 0) {
219	                int32_t curVal = histLocal.GetValue(b);
220	                histLocal.SetValue(b, curVal + count);
221	            }
222	        }
223	    }
224	
225	    // --- Data members ---
226	    AscendC::TPipe pipe_;
227	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
228	
229	    AscendC::TBuf<AscendC::TPosition::VECCALC> byteBuf_;
230	    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;
231	
232	    // AIC-only buffers
233	    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf_;
234	    AscendC::TBuf<AscendC::TPosition::VECCALC> cntBuf_;
235	    AscendC::TBuf<AscendC::TPosition::VECCALC> onesBuf_;
236	    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf_;
237	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
238	
239	    AscendC::GlobalTensor<T> inputGlobal_;
240	    AscendC::GlobalTensor<int32_t> wsGlobal_;
241	
242	    uint32_t totalElems_{0};
243	    int32_t numCores_{0};
244	    int32_t elemsPerCore_{0};
245	    int32_t shiftBits_{0};
246	    uint32_t coreIdx_{0};
247	    uint32_t base_{0};
248	    uint32_t localElems_{0};
249	    uint32_t numTiles_{0};
250	};
251	
252	// ---------------------------------------------------------------------------
253	// KernelHansEncodeReduce — 1 core aggregates workspace rows -> output
254	// ---------------------------------------------------------------------------
255	class KernelHansEncodeReduce {
256	public:
257	    __aicore__ inline void Init(
258	        GM_ADDR outputGM,
259	        GM_ADDR workspaceGM,
260	        int32_t numCores)
261	    {
262	        numCores_ = numCores;
263	
264	        outputGlobal_.SetGlobalBuffer(
265	            reinterpret_cast<__gm__ int32_t*>(outputGM), HIST_SIZE);
266	        wsGlobal_.SetGlobalBuffer(
267	            reinterpret_cast<__gm__ int32_t*>(workspaceGM),
268	            static_cast<uint64_t>(numCores_) * HIST_SIZE);
269	
270	        pipe_.InitBuffer(inQueue_, BUFFER_NUM, HIST_SIZE * sizeof(int32_t));
271	        pipe_.InitBuffer(outQueue_, BUFFER_NUM, HIST_SIZE * sizeof(int32_t));
272	    }
273	
274	    __aicore__ inline void Process()
275	    {
276	        auto outLocal = outQueue_.AllocTensor<int32_t>();
277	        AscendC::Duplicate(outLocal, static_cast<int32_t>(0), HIST_SIZE);
278	        outQueue_.EnQue(outLocal);
279	
280	        for (int32_t c = 0; c < numCores_; ++c) {
281	            auto rowLocal = inQueue_.AllocTensor<int32_t>();
282	            auto srcOffset = wsGlobal_[static_cast<uint64_t>(c) * HIST_SIZE];
283	            LoadGmToUbPad<int32_t>(rowLocal, srcOffset,
284	                                   static_cast<uint32_t>(HIST_SIZE));
285	            inQueue_.EnQue(rowLocal);
286	
287	            auto row = inQueue_.DeQue<int32_t>();
288	            outLocal = outQueue_.DeQue<int32_t>();
289	            AscendC::Add(outLocal, outLocal, row, HIST_SIZE);
290	            outQueue_.EnQue(outLocal);
291	            inQueue_.FreeTensor(row);
292	        }
293	
294	        auto finalOut = outQueue_.DeQue<int32_t>();
295	        StoreUbToGmPad<int32_t>(outputGlobal_, finalOut,
296	                                static_cast<uint32_t>(HIST_SIZE));
297	        outQueue_.FreeTensor(finalOut);
298	    }
299	
300	private:
301	    AscendC::TPipe pipe_;
302	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
303	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
304	
305	    AscendC::GlobalTensor<int32_t> outputGlobal_;
306	    AscendC::GlobalTensor<int32_t> wsGlobal_;
307	    int32_t numCores_{0};
308	};
309	
310	// ---------------------------------------------------------------------------
311	// Kernel entry points
312	// ---------------------------------------------------------------------------
313	
314	extern "C" __global__ __aicore__ void hans_encode_compute(
315	    GM_ADDR inputGM,
316	    GM_ADDR workspaceGM,
317	    int32_t totalElems,
318	    int32_t numCores,
319	    int32_t elemsPerCore,
320	    int32_t shiftBits)
321	{
322	    if (shiftBits == 24) {
323	        KernelHansEncodeCompute<float> kernel;
324	        kernel.Init(inputGM, workspaceGM,
325	                    totalElems, numCores, elemsPerCore, shiftBits);
326	        kernel.Process();
327	    } else {
328	        KernelHansEncodeCompute<half> kernel;
329	        kernel.Init(inputGM, workspaceGM,
330	                    totalElems, numCores, elemsPerCore, shiftBits);
331	        kernel.Process();
332	    }
333	}
334	
335	extern "C" __global__ __aicore__ void hans_encode_reduce(
336	    GM_ADDR outputGM,
337	    GM_ADDR workspaceGM,
338	    int32_t totalElems,
339	    int32_t numCores,
340	    int32_t elemsPerCore,
341	    int32_t shiftBits)
342	{
343	    KernelHansEncodeReduce kernel;
344	    kernel.Init(outputGM, workspaceGM, numCores);
345	    kernel.Process();
346	}
