 */

// HansDecode AscendC kernel — decode Hans-encoded float data
// Reconstructs original float tensor from compressed components:
//   mantissa (mantissa bytes as float),
//   fixed (compressed bit stream as float),
//   var (uncompressed tail),
//   hist (int32 exponent histogram)
//
// All processing is single-core due to sequential bit-stream parsing.

#include "kernel_operator.h"

constexpr int32_t BLOCK_SIZE = 64;         // sub-block size
constexpr int32_t BIG_BLOCK = 4096;        // 64 * 64 = main block size
constexpr int32_t HIST_SIZE = 256;
constexpr int32_t META_SIZE = 128;         // meta_info uint16 count
constexpr int32_t MAX_BIG_LOOP = 32;       // max big_loop iterations

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    return (a + b - 1U) / b;
}

// ---------------------------------------------------------------------------
// KernelHansDecode
// ---------------------------------------------------------------------------
class KernelHansDecode {
public:
    __aicore__ inline void Init(
        GM_ADDR outputGM,
        GM_ADDR inputGM,
        GM_ADDR mantissaGM,
        GM_ADDR fixedGM,
        GM_ADDR varGM,
        GM_ADDR histGM,
        int32_t totalElems,
        int32_t totalMantissaFloat,
        int32_t totalFixedFloat,
        int32_t dtypeBytes,
        int32_t mantissaBytes,
        int32_t shiftBits,
        int32_t reshuffVal)
    {
        totalElems_     = static_cast<uint32_t>(totalElems);
        totalMantissaF_ = static_cast<uint32_t>(totalMantissaFloat);
        totalFixedF_    = static_cast<uint32_t>(totalFixedFloat);
        dtypeBytes_     = static_cast<uint32_t>(dtypeBytes);
        mantissaBytes_  = static_cast<uint32_t>(mantissaBytes);
        shiftBits_      = static_cast<uint32_t>(shiftBits);

        bigLoop_ = totalElems_ / BIG_BLOCK;

        // Global tensor setup
        outputGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(outputGM),
            totalElems_ * dtypeBytes_);
        inputGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(inputGM),
            totalElems_ * dtypeBytes_);
        mantissaGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(mantissaGM),
            totalMantissaF_ * dtypeBytes_);
        fixedGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(fixedGM),
            totalFixedF_ * dtypeBytes_);
        varGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(varGM),
            totalFixedF_ * dtypeBytes_);
        histGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t*>(histGM), HIST_SIZE);

        // UB buffer allocation
        // histogram: 256 * 4 = 1024 bytes
        pipe_.InitBuffer(histBuf_, HIST_SIZE * sizeof(int32_t));
        // sort indices: 256 * 4 = 1024 bytes
        pipe_.InitBuffer(sortIdxBuf_, HIST_SIZE * sizeof(int32_t));
        // ranking: 256 * 4 = 1024 bytes
        pipe_.InitBuffer(rankingBuf_, HIST_SIZE * sizeof(int32_t));
        // inverse ranking: 256 * 4 = 1024 bytes
        pipe_.InitBuffer(invRankBuf_, HIST_SIZE * sizeof(int32_t));
        // block_bit_num: 64 * 4 = 256 bytes
        pipe_.InitBuffer(blockBitNumBuf_, BLOCK_SIZE * sizeof(int32_t));
        // buffer: 4096 * 4 = 16384 bytes
        pipe_.InitBuffer(bufferBuf_, BIG_BLOCK * sizeof(int32_t));
        // exp_array (reconstructed): 4096 bytes
        pipe_.InitBuffer(expBuf_, BIG_BLOCK * sizeof(uint8_t));
        // mantissa tile for reconstruction: up to 3 * BIG_BLOCK bytes
        pipe_.InitBuffer(mantissaTileBuf_, 3 * BIG_BLOCK * sizeof(uint8_t));
        // stream tile (chunk of fixed as uint16): 2048 uint16 = 4096 bytes
        pipe_.InitBuffer(streamBuf_, 2048 * sizeof(uint16_t));
        // sorted hist for ranking computation
        pipe_.InitBuffer(sortTmpBuf_, 512 * sizeof(uint8_t));
    }

    __aicore__ inline void Process()
    {
        // Step 1: Load histogram and compute ranking
        ComputeRanking();

        // Step 2: Initialize state
        auto blockBitNum = blockBitNumBuf_.template Get<int32_t>();
        auto buffer = bufferBuf_.template Get<int32_t>();
        AscendC::Duplicate(blockBitNum, static_cast<int32_t>(0), BLOCK_SIZE);
        AscendC::Duplicate(buffer, static_cast<int32_t>(0), BIG_BLOCK);

        // Step 3: Reinterpret fixed tensor as uint16 bit-stream
        // fixed has totalFixedF_ float elements = totalFixedF_ * dtypeBytes_ bytes
        // = totalFixedF_ * dtypeBytes_ / 2 uint16 values
        uint32_t streamLenU16 = totalFixedF_ * dtypeBytes_ / 2U;

        // Step 4: Parse meta_info (first 128 uint16 = 256 bytes)
        // Parse in chunks using UB
        auto streamLocal = streamBuf_.template Get<uint16_t>();
        uint32_t streamPos = 0U;

        // Read meta_info
        LoadStreamChunk(streamLocal, streamPos, META_SIZE);
        streamPos += META_SIZE;

        // Extract key meta fields
        // meta[2] = totalElems / 64, meta[8] = total_compressed_size (bytes)
        uint32_t numBlocks64 = static_cast<uint32_t>(streamLocal.GetValue(2));
        uint32_t compressedSize = static_cast<uint32_t>(streamLocal.GetValue(8));
        // compressedSize is total size in bytes of compressed data (uint16 stream = compressedSize/2)

        // Step 5: Main decode loop — process each 4096-element block
        uint32_t expElemPos = 0U;  // position in exp_array (per-block reset)

        for (uint32_t blk = 0U; blk < bigLoop_; ++blk) {
            // 5a. Find max_bit in the stream
            uint16_t maxBitLocal[BLOCK_SIZE];
            uint32_t overflowCountU16 = 0U;

            // Scan for max_bit (64 uint16 values with all ≤ 32)
            bool found = false;
            uint32_t scanPos = streamPos;
            while (!found && scanPos + BLOCK_SIZE <= streamLenU16) {
                LoadStreamChunk(streamLocal, scanPos, BLOCK_SIZE);
                scanPos += BLOCK_SIZE;

                bool allValid = true;
                for (uint32_t j = 0U; j < BLOCK_SIZE; ++j) {
                    uint16_t val = streamLocal.GetValue(j);
                    if (val > 32U) {
                        allValid = false;
                        break;
                    }
                    maxBitLocal[j] = val;
                }
                if (allValid) {
                    found = true;
                } else {
                    overflowCountU16 += BLOCK_SIZE;
                }
            }

            // Calculate overflow element count
            uint32_t overflowCount = (scanPos - streamPos - BLOCK_SIZE) / BLOCK_SIZE;
            // overflowCount == 0 means no overflow, > 0 means overflow
            uint32_t maxBitPos = scanPos - BLOCK_SIZE;
            streamPos = scanPos;  // past max_bit

            // 5b. Update block_bit_num
            int32_t cmpMask[BLOCK_SIZE];
            bool hasOverflow = false;
            for (uint32_t j = 0U; j < BLOCK_SIZE; ++j) {
                int32_t curBit = blockBitNum.GetValue(j);
                int32_t mb = static_cast<int32_t>(maxBitLocal[j]);
                int32_t newBit = curBit + mb;
                blockBitNum.SetValue(j, newBit);
                cmpMask[j] = (newBit > 16) ? 1 : 0;
                if (cmpMask[j]) hasOverflow = true;
            }
            AscendC::PipeBarrier<PIPE_V>();

            // 5c. Process overflow data if any
            if (hasOverflow && overflowCount > 0U) {
                // Read overflow data for overflowing sub-blocks
                // overflow data precedes max_bit in stream
                uint32_t ovStart = maxBitPos - overflowCount * BLOCK_SIZE;
                uint32_t ovIdx = 0U;
                for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
                    if (cmpMask[sj]) {
                        // This sub-block overflowed: read its 64 overflow values
                        uint32_t subBlockOvStart = ovStart + ovIdx * BLOCK_SIZE;
                        LoadStreamChunk(streamLocal, subBlockOvStart, BLOCK_SIZE);
                        uint32_t elemBase = sj * BLOCK_SIZE;
                        for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                            int32_t curBuf = buffer.GetValue(elemBase + ei);
                            uint16_t ovVal = streamLocal.GetValue(ei);
                            int32_t newBuf = (curBuf << 16) | static_cast<int32_t>(ovVal);
                            buffer.SetValue(elemBase + ei, newBuf);
                        }
                        ovIdx++;
                        int32_t curBit = blockBitNum.GetValue(sj);
                        blockBitNum.SetValue(sj, curBit - 16);
                    }
                }
                AscendC::PipeBarrier<PIPE_V>();
            }

            // 5d. Decode: extract exp_sort_idx and map to exponent bytes
            auto expLocal = expBuf_.template Get<uint8_t>();
            auto invRank = invRankBuf_.template Get<int32_t>();

            for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
                int32_t mb = static_cast<int32_t>(maxBitLocal[sj]);
                uint32_t elemBase = sj * BLOCK_SIZE;

                if (mb == 0) {
                    // Zero bit width: all elements in this sub-block have rank 0
                    // Rank 0 maps to invRank[0]
                    int32_t expByte = invRank.GetValue(0);
                    uint8_t eb = static_cast<uint8_t>(expByte);
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                        expLocal.SetValue(elemBase + ei, eb);
                    }
                } else {
                    // Non-zero bit width: extract rank from buffer
                    int32_t mask = (1 << mb) - 1;
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                        int32_t bufVal = buffer.GetValue(elemBase + ei);
                        int32_t rank = bufVal & mask;
                        int32_t expByte = invRank.GetValue(rank);
                        expLocal.SetValue(elemBase + ei,
                            static_cast<uint8_t>(expByte));
                        // Update buffer for next iteration
                        buffer.SetValue(elemBase + ei, bufVal >> mb);
                    }
                }
            }
            AscendC::PipeBarrier<PIPE_V>();

            // 5e. Reconstruct float values from exponent + mantissa
            ReconstructFloatsBlock(expLocal, blk);

            expElemPos += BIG_BLOCK;
        }

        // Step 6: After all blocks, reconstruct remaining elements from var
        // var holds the uncompressed leading elements
        // For float32: copy var elements to output directly
        // For float16: similar
        ReconstructVarElements();

        // Step 7: Copy output to GM
        CopyOutputToGM();
    }

private:
    // -----------------------------------------------------------------------
    // ComputeRanking: Sort histogram descending, compute ranking and inverse
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeRanking()
    {
        auto histLocal   = histBuf_.template Get<int32_t>();
        auto sortIdx     = sortIdxBuf_.template Get<int32_t>();
        auto ranking     = rankingBuf_.template Get<int32_t>();
        auto invRank     = invRankBuf_.template Get<int32_t>();

        // Load hist from GM
        AscendC::DataCopyExtParams copyP = {
            1U, static_cast<uint32_t>(HIST_SIZE * sizeof(int32_t)), 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<int32_t> padP = {true, 0U, 0U, static_cast<int32_t>(0)};
        AscendC::DataCopyPad(histLocal, histGlobal_, copyP, padP);
        AscendC::PipeBarrier<PIPE_V>();

        // Initialize sort indices 0..255
        for (int32_t i = 0; i < HIST_SIZE; ++i) {
            sortIdx.SetValue(i, i);
        }

        // Bubble sort descending by hist value, using sortIdx as index array
        // Since HIST_SIZE = 256 is small, scalar sorting is acceptable
        for (int32_t i = 0; i < HIST_SIZE - 1; ++i) {
            for (int32_t j = 0; j < HIST_SIZE - 1 - i; ++j) {
                int32_t idxJ   = sortIdx.GetValue(j);
                int32_t idxJ1  = sortIdx.GetValue(j + 1);
                int32_t valJ   = histLocal.GetValue(idxJ);
                int32_t valJ1  = histLocal.GetValue(idxJ1);
                if (valJ < valJ1) {
                    sortIdx.SetValue(j, idxJ1);
                    sortIdx.SetValue(j + 1, idxJ);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Build ranking: ranking[exponent_byte] = rank (0 = most frequent)
        for (int32_t r = 0; r < HIST_SIZE; ++r) {
            int32_t expByte = sortIdx.GetValue(r);
            ranking.SetValue(expByte, r);
            invRank.SetValue(r, expByte);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    // -----------------------------------------------------------------------
    // LoadStreamChunk: Load a chunk of the fixed tensor as uint16 into UB
    // -----------------------------------------------------------------------
    __aicore__ inline void LoadStreamChunk(
        AscendC::LocalTensor<uint16_t> &dst,
        uint32_t startU16,
        uint32_t count)
    {
        // fixed is stored as float/dtype in GM, reinterpret as uint16
        uint32_t byteOffset = startU16 * 2U;  // each uint16 = 2 bytes
        auto srcGM = fixedGlobal_[byteOffset];
        AscendC::DataCopyExtParams copyP = {
            1U, count * 2U, 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<uint16_t> padP = {
            true, 0U, 0U, static_cast<uint16_t>(0)};
        AscendC::DataCopyPad(dst, srcGM, copyP, padP);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // -----------------------------------------------------------------------
    // ReconstructFloatsBlock: Combine exponent + mantissa → float per block
    // -----------------------------------------------------------------------
    __aicore__ inline void ReconstructFloatsBlock(
        AscendC::LocalTensor<uint8_t> &expLocal,
        uint32_t blockIdx)
    {
        auto mTile = mantissaTileBuf_.template Get<uint8_t>();

        if (dtypeBytes_ == 4U) {
            // float32: [m0, m1, m2, exp]
            // mantissa has 3 bytes per float element
            uint32_t mByteOffset = blockIdx * BIG_BLOCK * 3U;

            // Load mantissa chunk (3 * BIG_BLOCK bytes)
            auto mSrc = mantissaGlobal_[mByteOffset];
            AscendC::DataCopyExtParams copyP = {
                1U, BIG_BLOCK * 3U, 0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<uint8_t> padP = {
                true, 0U, 0U, static_cast<uint8_t>(0)};
            AscendC::DataCopyPad(mTile, mSrc, copyP, padP);
            AscendC::PipeBarrier<PIPE_V>();

            // Assemble float32: m0, m1, m2, exp
            // Write directly to output
            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                uint8_t m0 = mTile.GetValue(i * 3U);
                uint8_t m1 = mTile.GetValue(i * 3U + 1U);
                uint8_t m2 = mTile.GetValue(i * 3U + 2U);
                uint8_t exp = expLocal.GetValue(i);

                uint32_t outOff = (blockIdx * BIG_BLOCK + i) * 4U;
                outputGlobal_.SetValue(outOff, m0);
                outputGlobal_.SetValue(outOff + 1U, m1);
                outputGlobal_.SetValue(outOff + 2U, m2);
                outputGlobal_.SetValue(outOff + 3U, exp);
            }
        } else {
            // float16/bf16: [m0, exp]
            // mantissa has 1 byte per float element
            uint32_t mByteOffset = blockIdx * BIG_BLOCK * 1U;

            auto mSrc = mantissaGlobal_[mByteOffset];
            AscendC::DataCopyExtParams copyP = {
                1U, BIG_BLOCK * 1U, 0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<uint8_t> padP = {
                true, 0U, 0U, static_cast<uint8_t>(0)};
            AscendC::DataCopyPad(mTile, mSrc, copyP, padP);
            AscendC::PipeBarrier<PIPE_V>();

            // Assemble float16: m0, exp
            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                uint8_t m0 = mTile.GetValue(i);
                uint8_t exp = expLocal.GetValue(i);

                uint32_t outOff = (blockIdx * BIG_BLOCK + i) * 2U;
                outputGlobal_.SetValue(outOff, m0);
                outputGlobal_.SetValue(outOff + 1U, exp);
            }
        }
    }

    // -----------------------------------------------------------------------
    // ReconstructVarElements: Copy var section to output
    // var is uncompressed leading elements of the original
    // -----------------------------------------------------------------------
    __aicore__ inline void ReconstructVarElements()
    {
        // The var tensor contains uncompressed data
        // For dtype consistency, copy var bytes to the beginning of output
        // var has totalFixedF_ elements of dtypeBytes_ each
        uint32_t varBytes = totalFixedF_ * dtypeBytes_;

        if (varBytes > 0U && varBytes <= totalElems_ * dtypeBytes_) {
            // Simple copy: output[0:varBytes] = var[0:varBytes]
            for (uint32_t b = 0U; b < varBytes; ++b) {
                uint8_t val = varGlobal_.GetValue(b);
                outputGlobal_.SetValue(b, val);
            }
        }
    }

    // -----------------------------------------------------------------------
    // CopyOutputToGM: Ensure output is flushed to GM
    // -----------------------------------------------------------------------
    __aicore__ inline void CopyOutputToGM()
    {
        AscendC::PipeBarrier<PIPE_V>();
    }

    // --- Data members ---
    AscendC::TPipe pipe_;

    // GM tensors
    AscendC::GlobalTensor<uint8_t> outputGlobal_;
    AscendC::GlobalTensor<uint8_t> inputGlobal_;
    AscendC::GlobalTensor<uint8_t> mantissaGlobal_;
    AscendC::GlobalTensor<uint8_t> fixedGlobal_;
    AscendC::GlobalTensor<uint8_t> varGlobal_;
    AscendC::GlobalTensor<int32_t> histGlobal_;

    // UB buffers (VECCALC)
    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sortIdxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rankingBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> invRankBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> blockBitNumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufferBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> expBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mantissaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> streamBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sortTmpBuf_;

    // Parameters
    uint32_t totalElems_{0};
    uint32_t totalMantissaF_{0};
    uint32_t totalFixedF_{0};
    uint32_t dtypeBytes_{0};
    uint32_t mantissaBytes_{0};
    uint32_t shiftBits_{0};
    uint32_t bigLoop_{0};
};

// ---------------------------------------------------------------------------
// Kernel entry point
// ---------------------------------------------------------------------------
extern "C" __global__ __aicore__ void hans_decode(
    GM_ADDR outputGM,
    GM_ADDR inputGM,
    GM_ADDR mantissaGM,
    GM_ADDR fixedGM,
    GM_ADDR varGM,
    GM_ADDR histGM,
    int32_t totalElems,
    int32_t totalMantissaFloat,
    int32_t totalFixedFloat,
    int32_t dtypeBytes,
    int32_t mantissaBytes,
    int32_t shiftBits,
    int32_t reshuffVal)
{
    KernelHansDecode kernel;
    kernel.Init(outputGM, inputGM, mantissaGM, fixedGM, varGM, histGM,
                totalElems, totalMantissaFloat, totalFixedFloat,
                dtypeBytes, mantissaBytes, shiftBits, reshuffVal);
    kernel.Process();
}
