// HansDecode op_host — host-side preparation and kernel launch
// Reconstructs original float tensor from Hans-encoded components.

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_hans_decode.h"

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------
namespace ascend_kernel {

at::Tensor hans_decode(
    const at::Tensor &input_tensor,
    const at::Tensor &mantissa,
    const at::Tensor &fixed,
    const at::Tensor &var,
    const at::Tensor &hist,
    int64_t reshuff)
{
    // --- Validate inputs ---
    TORCH_CHECK(input_tensor.is_contiguous(), "input_tensor must be contiguous");
    TORCH_CHECK(mantissa.is_contiguous(), "mantissa must be contiguous");
    TORCH_CHECK(fixed.is_contiguous(), "fixed must be contiguous");
    TORCH_CHECK(var.is_contiguous(), "var must be contiguous");
    TORCH_CHECK(hist.is_contiguous(), "hist must be contiguous");

    TORCH_CHECK(
        input_tensor.scalar_type() == at::kFloat ||
        input_tensor.scalar_type() == at::kHalf ||
        input_tensor.scalar_type() == at::kBFloat16,
        "input_tensor must be float32, float16, or bfloat16");

    // --- Derive parameters ---
    int32_t totalElems = static_cast<int32_t>(input_tensor.numel());
    int32_t totalMantissaFloat = static_cast<int32_t>(mantissa.numel());
    int32_t totalFixedFloat = static_cast<int32_t>(fixed.numel());

    // Dtype-derived parameters
    int32_t dtypeBytes = 4;    // float32
    int32_t mantissaBytes = 3; // float32: 3 mantissa bytes
    int32_t shiftBits = 24;    // float32: exponent in byte 3

    if (input_tensor.scalar_type() == at::kHalf ||
        input_tensor.scalar_type() == at::kBFloat16) {
        dtypeBytes = 2;
        mantissaBytes = 1;
        shiftBits = 8;
    }

    // --- Output tensor (same shape and dtype as input_tensor) ---
    at::Tensor output = at::empty_like(input_tensor);

    // Flatten tensors for kernel processing
    at::Tensor inputFlat = input_tensor.contiguous().view({totalElems});
    at::Tensor mantissaFlat = mantissa.contiguous().view({totalMantissaFloat});
    at::Tensor fixedFlat = fixed.contiguous().view({totalFixedFloat});
    at::Tensor varFlat = var.contiguous().view({totalFixedFloat});
    at::Tensor histFlat = hist.contiguous().view({256}).to(at::kInt);
    at::Tensor outputFlat = output.contiguous().view({totalElems});

    // --- Left-values for EXEC_KERNEL_CMD ---
    uint32_t blockDim = 1U;  // single-core processing
    int32_t reshuffVal = (reshuff != 0) ? 1 : 0;

    EXEC_KERNEL_CMD(hans_decode, blockDim,
                    outputFlat, inputFlat, mantissaFlat, fixedFlat,
                    varFlat, histFlat,
                    totalElems, totalMantissaFloat, totalFixedFloat,
                    dtypeBytes, mantissaBytes, shiftBits, reshuffVal);

    return output;
}

}  // namespace ascend_kernel
