1	/*
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
3	 * Licensed under the CANN Open Software License Agreement Version 2.0.
4	 */
5	
6	// HansDecode AscendC kernel — decode Hans-encoded float data
7	// Reconstructs original float tensor from compressed components:
8	//   mantissa (mantissa bytes as float),
9	//   fixed (compressed bit stream as float),
10	//   var (uncompressed tail),
11	//   hist (int32 exponent histogram)
12	//
13	// All processing is single-core due to sequential bit-stream parsing.
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BLOCK_SIZE = 64;         // sub-block size
18	constexpr int32_t BIG_BLOCK = 4096;        // 64 * 64 = main block size
19	constexpr int32_t HIST_SIZE = 256;
20	constexpr int32_t META_SIZE = 128;         // meta_info uint16 count
21	constexpr int32_t MAX_BIG_LOOP = 32;       // max big_loop iterations
22	
23	// ---------------------------------------------------------------------------
24	// Helpers
25	// ---------------------------------------------------------------------------
26	
27	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
28	{
29	    return (a + b - 1U) / b;
30	}
31	
32	// ---------------------------------------------------------------------------
33	// KernelHansDecode
34	// ---------------------------------------------------------------------------
35	class KernelHansDecode {
36	public:
37	    __aicore__ inline void Init(
38	        GM_ADDR outputGM,
39	        GM_ADDR inputGM,
40	        GM_ADDR mantissaGM,
41	        GM_ADDR fixedGM,
42	        GM_ADDR varGM,
43	        GM_ADDR histGM,
44	        int32_t totalElems,
45	        int32_t totalMantissaFloat,
46	        int32_t totalFixedFloat,
47	        int32_t dtypeBytes,
48	        int32_t mantissaBytes,
49	        int32_t shiftBits,
50	        int32_t reshuffVal)
51	    {
52	        totalElems_     = static_cast<uint32_t>(totalElems);
53	        totalMantissaF_ = static_cast<uint32_t>(totalMantissaFloat);
54	        totalFixedF_    = static_cast<uint32_t>(totalFixedFloat);
55	        dtypeBytes_     = static_cast<uint32_t>(dtypeBytes);
56	        mantissaBytes_  = static_cast<uint32_t>(mantissaBytes);
57	        shiftBits_      = static_cast<uint32_t>(shiftBits);
58	
59	        bigLoop_ = totalElems_ / BIG_BLOCK;
60	
61	        // Global tensor setup
62	        outputGlobal_.SetGlobalBuffer(
63	            reinterpret_cast<__gm__ uint8_t*>(outputGM),
64	            totalElems_ * dtypeBytes_);
65	        inputGlobal_.SetGlobalBuffer(
66	            reinterpret_cast<__gm__ uint8_t*>(inputGM),
67	            totalElems_ * dtypeBytes_);
68	        mantissaGlobal_.SetGlobalBuffer(
69	            reinterpret_cast<__gm__ uint8_t*>(mantissaGM),
70	            totalMantissaF_ * dtypeBytes_);
71	        fixedGlobal_.SetGlobalBuffer(
72	            reinterpret_cast<__gm__ uint8_t*>(fixedGM),
73	            totalFixedF_ * dtypeBytes_);
74	        varGlobal_.SetGlobalBuffer(
75	            reinterpret_cast<__gm__ uint8_t*>(varGM),
76	            totalFixedF_ * dtypeBytes_);
77	        histGlobal_.SetGlobalBuffer(
78	            reinterpret_cast<__gm__ int32_t*>(histGM), HIST_SIZE);
79	
80	        // UB buffer allocation
81	        // histogram: 256 * 4 = 1024 bytes
82	        pipe_.InitBuffer(histBuf_, HIST_SIZE * sizeof(int32_t));
83	        // sort indices: 256 * 4 = 1024 bytes
84	        pipe_.InitBuffer(sortIdxBuf_, HIST_SIZE * sizeof(int32_t));
85	        // ranking: 256 * 4 = 1024 bytes
86	        pipe_.InitBuffer(rankingBuf_, HIST_SIZE * sizeof(int32_t));
87	        // inverse ranking: 256 * 4 = 1024 bytes
88	        pipe_.InitBuffer(invRankBuf_, HIST_SIZE * sizeof(int32_t));
89	        // block_bit_num: 64 * 4 = 256 bytes
90	        pipe_.InitBuffer(blockBitNumBuf_, BLOCK_SIZE * sizeof(int32_t));
91	        // buffer: 4096 * 4 = 16384 bytes
92	        pipe_.InitBuffer(bufferBuf_, BIG_BLOCK * sizeof(int32_t));
93	        // exp_array (reconstructed): 4096 bytes
94	        pipe_.InitBuffer(expBuf_, BIG_BLOCK * sizeof(uint8_t));
95	        // mantissa tile for reconstruction: up to 3 * BIG_BLOCK bytes
96	        pipe_.InitBuffer(mantissaTileBuf_, 3 * BIG_BLOCK * sizeof(uint8_t));
97	        // stream tile (chunk of fixed as uint16): 2048 uint16 = 4096 bytes
98	        pipe_.InitBuffer(streamBuf_, 2048 * sizeof(uint16_t));
99	        // sorted hist for ranking computation
100	        pipe_.InitBuffer(sortTmpBuf_, 512 * sizeof(uint8_t));
101	    }
102	
103	    __aicore__ inline void Process()
104	    {
105	        // Step 1: Load histogram and compute ranking
106	        ComputeRanking();
107	
108	        // Step 2: Initialize state
109	        auto blockBitNum = blockBitNumBuf_.template Get<int32_t>();
110	        auto buffer = bufferBuf_.template Get<int32_t>();
111	        AscendC::Duplicate(blockBitNum, static_cast<int32_t>(0), BLOCK_SIZE);
112	        AscendC::Duplicate(buffer, static_cast<int32_t>(0), BIG_BLOCK);
113	
114	        // Step 3: Reinterpret fixed tensor as uint16 bit-stream
115	        // fixed has totalFixedF_ float elements = totalFixedF_ * dtypeBytes_ bytes
116	        // = totalFixedF_ * dtypeBytes_ / 2 uint16 values
117	        uint32_t streamLenU16 = totalFixedF_ * dtypeBytes_ / 2U;
118	
119	        // Step 4: Parse meta_info (first 128 uint16 = 256 bytes)
120	        // Parse in chunks using UB
121	        auto streamLocal = streamBuf_.template Get<uint16_t>();
122	        uint32_t streamPos = 0U;
123	
124	        // Read meta_info
125	        LoadStreamChunk(streamLocal, streamPos, META_SIZE);
126	        streamPos += META_SIZE;
127	
128	        // Extract key meta fields
129	        // meta[2] = totalElems / 64, meta[8] = total_compressed_size (bytes)
130	        uint32_t numBlocks64 = static_cast<uint32_t>(streamLocal.GetValue(2));
131	        uint32_t compressedSize = static_cast<uint32_t>(streamLocal.GetValue(8));
132	        // compressedSize is total size in bytes of compressed data (uint16 stream = compressedSize/2)
133	
134	        // Step 5: Main decode loop — process each 4096-element block
135	        uint32_t expElemPos = 0U;  // position in exp_array (per-block reset)
136	
137	        for (uint32_t blk = 0U; blk < bigLoop_; ++blk) {
138	            // 5a. Find max_bit in the stream
139	            uint16_t maxBitLocal[BLOCK_SIZE];
140	            uint32_t overflowCountU16 = 0U;
141	
142	            // Scan for max_bit (64 uint16 values with all ≤ 32)
143	            bool found = false;
144	            uint32_t scanPos = streamPos;
145	            while (!found && scanPos + BLOCK_SIZE <= streamLenU16) {
146	                LoadStreamChunk(streamLocal, scanPos, BLOCK_SIZE);
147	                scanPos += BLOCK_SIZE;
148	
149	                bool allValid = true;
150	                for (uint32_t j = 0U; j < BLOCK_SIZE; ++j) {
151	                    uint16_t val = streamLocal.GetValue(j);
152	                    if (val > 32U) {
153	                        allValid = false;
154	                        break;
155	                    }
156	                    maxBitLocal[j] = val;
157	                }
158	                if (allValid) {
159	                    found = true;
160	                } else {
161	                    overflowCountU16 += BLOCK_SIZE;
162	                }
163	            }
164	
165	            // Calculate overflow element count
166	            uint32_t overflowCount = (scanPos - streamPos - BLOCK_SIZE) / BLOCK_SIZE;
167	            // overflowCount == 0 means no overflow, > 0 means overflow
168	            uint32_t maxBitPos = scanPos - BLOCK_SIZE;
169	            streamPos = scanPos;  // past max_bit
170	
171	            // 5b. Update block_bit_num
172	            int32_t cmpMask[BLOCK_SIZE];
173	            bool hasOverflow = false;
174	            for (uint32_t j = 0U; j < BLOCK_SIZE; ++j) {
175	                int32_t curBit = blockBitNum.GetValue(j);
176	                int32_t mb = static_cast<int32_t>(maxBitLocal[j]);
177	                int32_t newBit = curBit + mb;
178	                blockBitNum.SetValue(j, newBit);
179	                cmpMask[j] = (newBit > 16) ? 1 : 0;
180	                if (cmpMask[j]) hasOverflow = true;
181	            }
182	            AscendC::PipeBarrier<PIPE_V>();
183	
184	            // 5c. Process overflow data if any
185	            if (hasOverflow && overflowCount > 0U) {
186	                // Read overflow data for overflowing sub-blocks
187	                // overflow data precedes max_bit in stream
188	                uint32_t ovStart = maxBitPos - overflowCount * BLOCK_SIZE;
189	                uint32_t ovIdx = 0U;
190	                for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
191	                    if (cmpMask[sj]) {
192	                        // This sub-block overflowed: read its 64 overflow values
193	                        uint32_t subBlockOvStart = ovStart + ovIdx * BLOCK_SIZE;
194	                        LoadStreamChunk(streamLocal, subBlockOvStart, BLOCK_SIZE);
195	                        uint32_t elemBase = sj * BLOCK_SIZE;
196	                        for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
197	                            int32_t curBuf = buffer.GetValue(elemBase + ei);
198	                            uint16_t ovVal = streamLocal.GetValue(ei);
199	                            int32_t newBuf = (curBuf << 16) | static_cast<int32_t>(ovVal);
200	                            buffer.SetValue(elemBase + ei, newBuf);
201	                        }
202	                        ovIdx++;
203	                        int32_t curBit = blockBitNum.GetValue(sj);
204	                        blockBitNum.SetValue(sj, curBit - 16);
205	                    }
206	                }
207	                AscendC::PipeBarrier<PIPE_V>();
208	            }
209	
210	            // 5d. Decode: extract exp_sort_idx and map to exponent bytes
211	            auto expLocal = expBuf_.template Get<uint8_t>();
212	            auto invRank = invRankBuf_.template Get<int32_t>();
213	
214	            for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
215	                int32_t mb = static_cast<int32_t>(maxBitLocal[sj]);
216	                uint32_t elemBase = sj * BLOCK_SIZE;
217	
218	                if (mb == 0) {
219	                    // Zero bit width: all elements in this sub-block have rank 0
220	                    // Rank 0 maps to invRank[0]
221	                    int32_t expByte = invRank.GetValue(0);
222	                    uint8_t eb = static_cast<uint8_t>(expByte);
223	                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
224	                        expLocal.SetValue(elemBase + ei, eb);
225	                    }
226	                } else {
227	                    // Non-zero bit width: extract rank from buffer
228	                    int32_t mask = (1 << mb) - 1;
229	                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
230	                        int32_t bufVal = buffer.GetValue(elemBase + ei);
231	                        int32_t rank = bufVal & mask;
232	                        int32_t expByte = invRank.GetValue(rank);
233	                        expLocal.SetValue(elemBase + ei,
234	                            static_cast<uint8_t>(expByte));
235	                        // Update buffer for next iteration
236	                        buffer.SetValue(elemBase + ei, bufVal >> mb);
237	                    }
238	                }
239	            }
240	            AscendC::PipeBarrier<PIPE_V>();
241	
242	            // 5e. Reconstruct float values from exponent + mantissa
243	            ReconstructFloatsBlock(expLocal, blk);
244	
245	            expElemPos += BIG_BLOCK;
246	        }
247	
248	        // Step 6: After all blocks, reconstruct remaining elements from var
249	        // var holds the uncompressed leading elements
250	        // For float32: copy var elements to output directly
251	        // For float16: similar
252	        ReconstructVarElements();
253	
254	        // Step 7: Copy output to GM
255	        CopyOutputToGM();
256	    }
257	
258	private:
259	    // -----------------------------------------------------------------------
260	    // ComputeRanking: Sort histogram descending, compute ranking and inverse
261	    // -----------------------------------------------------------------------
262	    __aicore__ inline void ComputeRanking()
263	    {
264	        auto histLocal   = histBuf_.template Get<int32_t>();
265	        auto sortIdx     = sortIdxBuf_.template Get<int32_t>();
266	        auto ranking     = rankingBuf_.template Get<int32_t>();
267	        auto invRank     = invRankBuf_.template Get<int32_t>();
268	
269	        // Load hist from GM
270	        AscendC::DataCopyExtParams copyP = {
271	            1U, static_cast<uint32_t>(HIST_SIZE * sizeof(int32_t)), 0U, 0U, 0U};
272	        AscendC::DataCopyPadExtParams<int32_t> padP = {true, 0U, 0U, static_cast<int32_t>(0)};
273	        AscendC::DataCopyPad(histLocal, histGlobal_, copyP, padP);
274	        AscendC::PipeBarrier<PIPE_V>();
275	
276	        // Initialize sort indices 0..255
277	        for (int32_t i = 0; i < HIST_SIZE; ++i) {
278	            sortIdx.SetValue(i, i);
279	        }
280	
281	        // Bubble sort descending by hist value, using sortIdx as index array
282	        // Since HIST_SIZE = 256 is small, scalar sorting is acceptable
283	        for (int32_t i = 0; i < HIST_SIZE - 1; ++i) {
284	            for (int32_t j = 0; j < HIST_SIZE - 1 - i; ++j) {
285	                int32_t idxJ   = sortIdx.GetValue(j);
286	                int32_t idxJ1  = sortIdx.GetValue(j + 1);
287	                int32_t valJ   = histLocal.GetValue(idxJ);
288	                int32_t valJ1  = histLocal.GetValue(idxJ1);
289	                if (valJ < valJ1) {
290	                    sortIdx.SetValue(j, idxJ1);
291	                    sortIdx.SetValue(j + 1, idxJ);
292	                }
293	            }
294	        }
295	        AscendC::PipeBarrier<PIPE_V>();
296	
297	        // Build ranking: ranking[exponent_byte] = rank (0 = most frequent)
298	        for (int32_t r = 0; r < HIST_SIZE; ++r) {
299	            int32_t expByte = sortIdx.GetValue(r);
300	            ranking.SetValue(expByte, r);
301	            invRank.SetValue(r, expByte);
302	        }
303	        AscendC::PipeBarrier<PIPE_V>();
304	    }
305	
306	    // -----------------------------------------------------------------------
307	    // LoadStreamChunk: Load a chunk of the fixed tensor as uint16 into UB
308	    // -----------------------------------------------------------------------
309	    __aicore__ inline void LoadStreamChunk(
310	        AscendC::LocalTensor<uint16_t> &dst,
311	        uint32_t startU16,
312	        uint32_t count)
313	    {
314	        // fixed is stored as float/dtype in GM, reinterpret as uint16
315	        uint32_t byteOffset = startU16 * 2U;  // each uint16 = 2 bytes
316	        auto srcGM = fixedGlobal_[byteOffset];
317	        AscendC::DataCopyExtParams copyP = {
318	            1U, count * 2U, 0U, 0U, 0U};
319	        AscendC::DataCopyPadExtParams<uint16_t> padP = {
320	            true, 0U, 0U, static_cast<uint16_t>(0)};
321	        AscendC::DataCopyPad(dst, srcGM, copyP, padP);
322	        AscendC::PipeBarrier<PIPE_V>();
323	    }
324	
325	    // -----------------------------------------------------------------------
326	    // ReconstructFloatsBlock: Combine exponent + mantissa → float per block
327	    // -----------------------------------------------------------------------
328	    __aicore__ inline void ReconstructFloatsBlock(
329	        AscendC::LocalTensor<uint8_t> &expLocal,
330	        uint32_t blockIdx)
331	    {
332	        auto mTile = mantissaTileBuf_.template Get<uint8_t>();
333	
334	        if (dtypeBytes_ == 4U) {
335	            // float32: [m0, m1, m2, exp]
336	            // mantissa has 3 bytes per float element
337	            uint32_t mByteOffset = blockIdx * BIG_BLOCK * 3U;
338	
339	            // Load mantissa chunk (3 * BIG_BLOCK bytes)
340	            auto mSrc = mantissaGlobal_[mByteOffset];
341	            AscendC::DataCopyExtParams copyP = {
342	                1U, BIG_BLOCK * 3U, 0U, 0U, 0U};
343	            AscendC::DataCopyPadExtParams<uint8_t> padP = {
344	                true, 0U, 0U, static_cast<uint8_t>(0)};
345	            AscendC::DataCopyPad(mTile, mSrc, copyP, padP);
346	            AscendC::PipeBarrier<PIPE_V>();
347	
348	            // Assemble float32: m0, m1, m2, exp
349	            // Write directly to output
350	            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
351	                uint8_t m0 = mTile.GetValue(i * 3U);
352	                uint8_t m1 = mTile.GetValue(i * 3U + 1U);
353	                uint8_t m2 = mTile.GetValue(i * 3U + 2U);
354	                uint8_t exp = expLocal.GetValue(i);
355	
356	                uint32_t outOff = (blockIdx * BIG_BLOCK + i) * 4U;
357	                outputGlobal_.SetValue(outOff, m0);
358	                outputGlobal_.SetValue(outOff + 1U, m1);
359	                outputGlobal_.SetValue(outOff + 2U, m2);
360	                outputGlobal_.SetValue(outOff + 3U, exp);
361	            }
362	        } else {
363	            // float16/bf16: [m0, exp]
364	            // mantissa has 1 byte per float element
365	            uint32_t mByteOffset = blockIdx * BIG_BLOCK * 1U;
366	
367	            auto mSrc = mantissaGlobal_[mByteOffset];
368	            AscendC::DataCopyExtParams copyP = {
369	                1U, BIG_BLOCK * 1U, 0U, 0U, 0U};
370	            AscendC::DataCopyPadExtParams<uint8_t> padP = {
371	                true, 0U, 0U, static_cast<uint8_t>(0)};
372	            AscendC::DataCopyPad(mTile, mSrc, copyP, padP);
373	            AscendC::PipeBarrier<PIPE_V>();
374	
375	            // Assemble float16: m0, exp
376	            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
377	                uint8_t m0 = mTile.GetValue(i);
378	                uint8_t exp = expLocal.GetValue(i);
379	
380	                uint32_t outOff = (blockIdx * BIG_BLOCK + i) * 2U;
381	                outputGlobal_.SetValue(outOff, m0);
382	                outputGlobal_.SetValue(outOff + 1U, exp);
383	            }
384	        }
385	    }
386	
387	    // -----------------------------------------------------------------------
388	    // ReconstructVarElements: Copy var section to output
389	    // var is uncompressed leading elements of the original
390	    // -----------------------------------------------------------------------
391	    __aicore__ inline void ReconstructVarElements()
392	    {
393	        // The var tensor contains uncompressed data
394	        // For dtype consistency, copy var bytes to the beginning of output
395	        // var has totalFixedF_ elements of dtypeBytes_ each
396	        uint32_t varBytes = totalFixedF_ * dtypeBytes_;
397	
398	        if (varBytes > 0U && varBytes <= totalElems_ * dtypeBytes_) {
399	            // Simple copy: output[0:varBytes] = var[0:varBytes]
400	            for (uint32_t b = 0U; b < varBytes; ++b) {
401	                uint8_t val = varGlobal_.GetValue(b);
402	                outputGlobal_.SetValue(b, val);
403	            }
404	        }
405	    }
406	
407	    // -----------------------------------------------------------------------
408	    // CopyOutputToGM: Ensure output is flushed to GM
409	    // -----------------------------------------------------------------------
410	    __aicore__ inline void CopyOutputToGM()
411	    {
412	        AscendC::PipeBarrier<PIPE_V>();
413	    }
