// HansDecode AscendC kernel — decode Hans-encoded float data
// Reconstructs original float tensor from compressed components.
//
// Design notes:
//   - Single-core processing due to sequential bit-parsing dependencies
//   - All GM↔UB transfers use DataCopyPad
//   - Output reconstruction in UB then DataCopyPad to GM
//   - Scalar operations for ranking, bit extraction, and byte assembly

#include "kernel_operator.h"

constexpr int32_t BLOCK_SIZE = 64;
constexpr int32_t BIG_BLOCK = 4096;
constexpr int32_t HIST_SIZE = 256;
constexpr int32_t META_SIZE = 128;
constexpr int32_t STREAM_CHUNK = 2048;  // uint16 values per stream chunk

// ---------------------------------------------------------------------------
// KernelHansDecode
// ---------------------------------------------------------------------------
class KernelHansDecode {
public:
    __aicore__ inline void Init(
        GM_ADDR outputGM,
        GM_ADDR inputGM,
        GM_ADDR mantissaGM,
        GM_ADDR fixedGM,
        GM_ADDR varGM,
        GM_ADDR histGM,
        int32_t totalElems,
        int32_t totalMantissaFloat,
        int32_t totalFixedFloat,
        int32_t dtypeBytes,
        int32_t mantissaBytes,
        int32_t shiftBits,
        int32_t reshuffVal)
    {
        totalElems_     = static_cast<uint32_t>(totalElems);
        totalMantissaF_ = static_cast<uint32_t>(totalMantissaFloat);
        totalFixedF_    = static_cast<uint32_t>(totalFixedFloat);
        dtypeBytes_     = static_cast<uint32_t>(dtypeBytes);
        mantissaBytes_  = static_cast<uint32_t>(mantissaBytes);
        shiftBits_      = static_cast<uint32_t>(shiftBits);

        uint32_t totalBytes = totalElems_ * dtypeBytes_;
        bigLoop_ = totalElems_ / BIG_BLOCK;

        // Global tensor setup — use uint8 for byte-level access
        outputGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(outputGM), totalBytes);
        inputGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(inputGM), totalBytes);
        mantissaGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(mantissaGM),
            totalMantissaF_ * dtypeBytes_);
        varGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(varGM),
            totalFixedF_ * dtypeBytes_);
        histGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t*>(histGM), HIST_SIZE);

        // uint16 view of fixed tensor for bit-stream parsing
        uint32_t fixedU16Count = totalFixedF_ * dtypeBytes_ / 2U;
        fixedU16Global_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint16_t*>(fixedGM), fixedU16Count);

        // UB buffers
        // hist: 256 * 4 = 1024
        pipe_.InitBuffer(histBuf_,  HIST_SIZE * sizeof(int32_t));
        // sort indices: 256 * 4 = 1024
        pipe_.InitBuffer(sortIdxBuf_, HIST_SIZE * sizeof(int32_t));
        // ranking: 256 * 4 = 1024
        pipe_.InitBuffer(rankingBuf_, HIST_SIZE * sizeof(int32_t));
        // inv ranking: 256 * 4 = 1024
        pipe_.InitBuffer(invRankBuf_, HIST_SIZE * sizeof(int32_t));
        // block_bit_num: 64 * 4 = 256
        pipe_.InitBuffer(blockBitNumBuf_, BLOCK_SIZE * sizeof(int32_t));
        // decode buffer: 4096 * 4 = 16384
        pipe_.InitBuffer(bufferBuf_, BIG_BLOCK * sizeof(int32_t));
        // exponent bytes: 4096
        pipe_.InitBuffer(expBuf_, BIG_BLOCK * sizeof(uint8_t));
        // mantissa tile: up to 3 * 4096 = 12288 bytes
        pipe_.InitBuffer(mantissaTileBuf_, 3 * BIG_BLOCK);
        // stream tile: up to 2048 * 2 = 4096 bytes (uint16)
        pipe_.InitBuffer(streamBuf_, STREAM_CHUNK * sizeof(uint16_t));
        // output tile: per-block reconstructed float bytes: max 4096*4 = 16384
        pipe_.InitBuffer(outputTileBuf_, BIG_BLOCK * 4U);
        // work buffer for vectorized compare (AIC path)
        pipe_.InitBuffer(workBuf_, BIG_BLOCK * sizeof(int32_t));
        // ones tile for select
        pipe_.InitBuffer(onesBuf_, BLOCK_SIZE * sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        // Step 1: Load histogram and compute ranking
        ComputeRanking();

        // Step 2: Init buffer state
        auto blockBitNum = blockBitNumBuf_.template Get<int32_t>();
        auto buffer = bufferBuf_.template Get<int32_t>();
        AscendC::Duplicate(blockBitNum, static_cast<int32_t>(0), BLOCK_SIZE);
        AscendC::Duplicate(buffer, static_cast<int32_t>(0), BIG_BLOCK);

        // Step 3: Parse bit-stream
        uint32_t streamLenU16 = totalFixedF_ * dtypeBytes_ / 2U;
        auto streamLocal = streamBuf_.template Get<uint16_t>();
        uint32_t streamPos = 0U;

        // Read meta_info header
        LoadStreamChunk(streamLocal, streamPos, META_SIZE);
        streamPos += META_SIZE;
        (void)streamLocal.GetValue(2);  // numBlocks64 (used for validation)
        (void)streamLocal.GetValue(8);  // compressedSize

        // Step 4: Main decode loop
        for (uint32_t blk = 0U; blk < bigLoop_; ++blk) {
            DecodeBlock(blk, streamLocal, streamLenU16, streamPos,
                        blockBitNum, buffer);
        }

        // Step 5: Copy var (leading uncompressed elements) to output
        CopyVarToOutput();
    }

private:
    // -------------------------------------------------------------------
    // DecodeBlock: Process one 4096-element block
    // -------------------------------------------------------------------
    __aicore__ inline void DecodeBlock(
        uint32_t blk,
        AscendC::LocalTensor<uint16_t> &streamLocal,
        uint32_t streamLenU16,
        uint32_t &streamPos,
        AscendC::LocalTensor<int32_t> &blockBitNum,
        AscendC::LocalTensor<int32_t> &buffer)
    {
        auto invRank = invRankBuf_.template Get<int32_t>();
        auto expLocal = expBuf_.template Get<uint8_t>();
        auto outTile  = outputTileBuf_.template Get<uint8_t>();

        // Find max_bit in stream: read until we find 64 valid uint16 values
        uint16_t maxBitLocal[BLOCK_SIZE];
        bool found = false;
        uint32_t scanPos = streamPos;
        while (!found && scanPos + BLOCK_SIZE <= streamLenU16) {
            LoadStreamChunk(streamLocal, scanPos, BLOCK_SIZE);
            scanPos += BLOCK_SIZE;
            bool allValid = true;
            for (uint32_t j = 0U; j < BLOCK_SIZE; ++j) {
                uint16_t val = streamLocal.GetValue(j);
                if (val > 32U) { allValid = false; break; }
                maxBitLocal[j] = val;
            }
            if (allValid) { found = true; }
        }
        streamPos = scanPos;  // advance past max_bit

        // Update block_bit_num and determine overflow
        int32_t  cmpMask[BLOCK_SIZE];
        bool     hasOverflow = false;
        for (uint32_t j = 0U; j < BLOCK_SIZE; ++j) {
            int32_t curBit = blockBitNum.GetValue(j);
            int32_t mb     = static_cast<int32_t>(maxBitLocal[j]);
            int32_t newBit = curBit + mb;
            blockBitNum.SetValue(j, newBit);
            cmpMask[j]    = (newBit > 16) ? 1 : 0;
            if (cmpMask[j]) hasOverflow = true;
        }

        // Decode exp_sort_idx from buffer
        for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
            int32_t  mb       = static_cast<int32_t>(maxBitLocal[sj]);
            uint32_t elemBase = sj * BLOCK_SIZE;

            if (mb == 0) {
                int32_t eb = invRank.GetValue(0);
                for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                    expLocal.SetValue(elemBase + ei, static_cast<uint8_t>(eb));
                }
            } else {
                int32_t mask = (1 << mb) - 1;
                for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                    int32_t bufVal = buffer.GetValue(elemBase + ei);
                    int32_t rank   = bufVal & mask;
                    int32_t eb     = invRank.GetValue(rank);
                    expLocal.SetValue(elemBase + ei,
                                      static_cast<uint8_t>(eb));
                    buffer.SetValue(elemBase + ei, bufVal >> mb);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Reconstruct float bytes for this block in outTile
        ReconstructFloats(blk, expLocal, outTile);
    }

    // -------------------------------------------------------------------
    // ReconstructFloats: Combine exponent + mantissa → float byte array
    // -------------------------------------------------------------------
    __aicore__ inline void ReconstructFloats(
        uint32_t blk,
        AscendC::LocalTensor<uint8_t> &expLocal,
        AscendC::LocalTensor<uint8_t> &outTile)
    {
        auto mTile = mantissaTileBuf_.template Get<uint8_t>();

        if (dtypeBytes_ == 4U) {
            uint32_t mByteOffset = blk * BIG_BLOCK * 3U;
            auto mSrc = mantissaGlobal_[mByteOffset];
            {
                AscendC::DataCopyExtParams cp = {
                    1U, BIG_BLOCK * 3U, 0U, 0U, 0U};
                AscendC::DataCopyPadExtParams<uint8_t> pp = {
                    true, 0U, 0U, static_cast<uint8_t>(0)};
                AscendC::DataCopyPad(mTile, mSrc, cp, pp);
            }
            AscendC::PipeBarrier<PIPE_V>();

            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                uint32_t obase = i * 4U;
                outTile.SetValue(obase + 0U, mTile.GetValue(i * 3U));
                outTile.SetValue(obase + 1U, mTile.GetValue(i * 3U + 1U));
                outTile.SetValue(obase + 2U, mTile.GetValue(i * 3U + 2U));
                outTile.SetValue(obase + 3U, expLocal.GetValue(i));
            }
            AscendC::PipeBarrier<PIPE_V>();

            // Write outTile to GM
            auto outDst = outputGlobal_[blk * BIG_BLOCK * 4U];
            {
                AscendC::DataCopyExtParams cp = {
                    1U, BIG_BLOCK * 4U, 0U, 0U, 0U};
                AscendC::DataCopyPad(outDst, outTile, cp);
            }
            AscendC::PipeBarrier<PIPE_V>();

        } else {
            // float16/bf16: 1 mantissa byte per element
            uint32_t mByteOffset = blk * BIG_BLOCK * 1U;
            auto mSrc = mantissaGlobal_[mByteOffset];
            {
                AscendC::DataCopyExtParams cp = {
                    1U, BIG_BLOCK * 1U, 0U, 0U, 0U};
                AscendC::DataCopyPadExtParams<uint8_t> pp = {
                    true, 0U, 0U, static_cast<uint8_t>(0)};
                AscendC::DataCopyPad(mTile, mSrc, cp, pp);
            }
            AscendC::PipeBarrier<PIPE_V>();

            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                outTile.SetValue(i * 2U,      mTile.GetValue(i));
                outTile.SetValue(i * 2U + 1U, expLocal.GetValue(i));
            }
            AscendC::PipeBarrier<PIPE_V>();

            auto outDst = outputGlobal_[blk * BIG_BLOCK * 2U];
            {
                AscendC::DataCopyExtParams cp = {
                    1U, BIG_BLOCK * 2U, 0U, 0U, 0U};
                AscendC::DataCopyPad(outDst, outTile, cp);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // -------------------------------------------------------------------
    // CopyVarToOutput: Copy var elements to beginning of output
    // -------------------------------------------------------------------
    __aicore__ inline void CopyVarToOutput()
    {
        uint32_t varBytes = totalFixedF_ * dtypeBytes_;
        if (varBytes == 0U) return;

        // Load var into UB then copy to output start
        auto tileBuf = outputTileBuf_.template Get<uint8_t>();
        uint32_t chunk = (varBytes < BIG_BLOCK * 4U) ? varBytes
                                                      : (BIG_BLOCK * 4U);

        for (uint32_t off = 0U; off < varBytes; off += chunk) {
            uint32_t cur = (off + chunk <= varBytes) ? chunk
                                                      : (varBytes - off);
            auto src = varGlobal_[off];
            {
                AscendC::DataCopyExtParams cp = {
                    1U, cur, 0U, 0U, 0U};
                AscendC::DataCopyPadExtParams<uint8_t> pp = {
                    true, 0U, 0U, static_cast<uint8_t>(0)};
                AscendC::DataCopyPad(tileBuf, src, cp, pp);
            }
            AscendC::PipeBarrier<PIPE_V>();

            auto dst = outputGlobal_[off];
            {
                AscendC::DataCopyExtParams cp2 = {1U, cur, 0U, 0U, 0U};
                AscendC::DataCopyPad(dst, tileBuf, cp2);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // -------------------------------------------------------------------
    // ComputeRanking: histogram → ranking → inverse ranking
    // -------------------------------------------------------------------
    __aicore__ inline void ComputeRanking()
    {
        auto histLocal = histBuf_.template Get<int32_t>();
        auto sortIdx   = sortIdxBuf_.template Get<int32_t>();
        auto ranking   = rankingBuf_.template Get<int32_t>();
        auto invRank   = invRankBuf_.template Get<int32_t>();

        // Load histogram from GM
        {
            AscendC::DataCopyExtParams cp = {
                1U, static_cast<uint32_t>(HIST_SIZE * sizeof(int32_t)),
                0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<int32_t> pp = {
                true, 0U, 0U, static_cast<int32_t>(0)};
            AscendC::DataCopyPad(histLocal, histGlobal_, cp, pp);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Init sort indices: 0..255
        for (int32_t i = 0; i < HIST_SIZE; ++i) {
            sortIdx.SetValue(i, i);
        }

        // Bubble sort descending
        for (int32_t i = 0; i < HIST_SIZE - 1; ++i) {
            for (int32_t j = 0; j < HIST_SIZE - 1 - i; ++j) {
                int32_t i0 = sortIdx.GetValue(j);
                int32_t i1 = sortIdx.GetValue(j + 1);
                int32_t v0 = histLocal.GetValue(i0);
                int32_t v1 = histLocal.GetValue(i1);
                if (v0 < v1) {
                    sortIdx.SetValue(j,     i1);
                    sortIdx.SetValue(j + 1, i0);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        // Build ranking
        for (int32_t r = 0; r < HIST_SIZE; ++r) {
            int32_t eb = sortIdx.GetValue(r);
            ranking.SetValue(eb, r);
            invRank.SetValue(r, eb);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    // -------------------------------------------------------------------
    // LoadStreamChunk: Load uint16 values from the fixed bit-stream
    // -------------------------------------------------------------------
    __aicore__ inline void LoadStreamChunk(
        AscendC::LocalTensor<uint16_t> &dst,
        uint32_t startU16,
        uint32_t count)
    {
        auto srcGM = fixedU16Global_[startU16];
        AscendC::DataCopyExtParams cp = {
            1U, count * static_cast<uint32_t>(sizeof(uint16_t)),
            0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<uint16_t> pp = {
            true, 0U, 0U, static_cast<uint16_t>(0)};
        AscendC::DataCopyPad(dst, srcGM, cp, pp);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // --- Data members ---
    AscendC::TPipe pipe_;

    // GM tensors
    AscendC::GlobalTensor<uint8_t>  outputGlobal_;
    AscendC::GlobalTensor<uint8_t>  inputGlobal_;
    AscendC::GlobalTensor<uint8_t>  mantissaGlobal_;
    AscendC::GlobalTensor<uint16_t> fixedU16Global_;
    AscendC::GlobalTensor<uint8_t>  varGlobal_;
    AscendC::GlobalTensor<int32_t>  histGlobal_;

    // UB buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sortIdxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rankingBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> invRankBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> blockBitNumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufferBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> expBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mantissaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> streamBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outputTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> onesBuf_;

    // Parameters
    uint32_t totalElems_{0};
    uint32_t totalMantissaF_{0};
    uint32_t totalFixedF_{0};
    uint32_t dtypeBytes_{0};
    uint32_t mantissaBytes_{0};
    uint32_t shiftBits_{0};
    uint32_t bigLoop_{0};
};

// ---------------------------------------------------------------------------
// Kernel entry point
// ---------------------------------------------------------------------------
extern "C" __global__ __aicore__ void hans_decode(
    GM_ADDR outputGM,
    GM_ADDR inputGM,
    GM_ADDR mantissaGM,
    GM_ADDR fixedGM,
    GM_ADDR varGM,
    GM_ADDR histGM,
    int32_t totalElems,
    int32_t totalMantissaFloat,
    int32_t totalFixedFloat,
    int32_t dtypeBytes,
    int32_t mantissaBytes,
    int32_t shiftBits,
    int32_t reshuffVal)
{
    KernelHansDecode kernel;
    kernel.Init(outputGM, inputGM, mantissaGM, fixedGM, varGM, histGM,
                totalElems, totalMantissaFloat, totalFixedFloat,
                dtypeBytes, mantissaBytes, shiftBits, reshuffVal);
    kernel.Process();
}
