// HansDecode AscendC kernel — decode Hans-encoded float data
//
// Algorithm:
//   The encoder packs ranks into a bit-stream across 16 big_loop iterations
//   (4096 elements each). Each iteration adds more bits per sub-block (64),
//   with overflow when a sub-block exceeds 16 bits.
//
//   Decoder MUST process big_loops in REVERSE order (15 → 0) to correctly
//   peel off the least-significant ranks first, then shift to expose earlier
//   ranks. Forward processing extracts wrong ranks because the buffer
//   accumulates across iterations.

#include "kernel_operator.h"
#include <cstdint>

constexpr int32_t BLOCK_SIZE   = 64;
constexpr int32_t BIG_BLOCK    = 4096;
constexpr int32_t HIST_SIZE    = 256;
constexpr int32_t META_SIZE    = 128;

// -----------------------------------------------------------------------
// KernelHansDecode
// -----------------------------------------------------------------------
class KernelHansDecode {
public:
    __aicore__ inline void Init(
        GM_ADDR outputGM, GM_ADDR inputGM,
        GM_ADDR mantissaGM, GM_ADDR fixedGM, GM_ADDR varGM, GM_ADDR histGM,
        int32_t totalElems,
        int32_t totalMantissaFloat, int32_t totalFixedFloat,
        int32_t dtypeBytes, int32_t mantissaBytes,
        int32_t shiftBits, int32_t reshuffVal)
    {
        totalElems_    = static_cast<uint32_t>(totalElems);
        totalMantissaF_ = static_cast<uint32_t>(totalMantissaFloat);
        totalFixedF_   = static_cast<uint32_t>(totalFixedFloat);
        dtypeBytes_    = static_cast<uint32_t>(dtypeBytes);
        mantissaBytes_ = static_cast<uint32_t>(mantissaBytes);
        shiftBits_     = static_cast<uint32_t>(shiftBits);

        bigLoop_       = totalElems_ / BIG_BLOCK;
        uint32_t ub    = totalElems_ * dtypeBytes_;

        outputGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t*>(outputGM), ub);
        inputGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t*>(inputGM), ub);
        mantissaGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(mantissaGM),
            totalMantissaF_ * dtypeBytes_);
        varGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t*>(varGM),
            totalFixedF_ * dtypeBytes_);
        histGlobal_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t*>(histGM), HIST_SIZE);

        uint32_t f16 = totalFixedF_ * dtypeBytes_ / 2U;
        fixedU16Global_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint16_t*>(fixedGM), f16);

        // UB buffers
        pipe_.InitBuffer(histBuf_, HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(sortIdxBuf_, HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(rankingBuf_, HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(invRankBuf_, HIST_SIZE * sizeof(int32_t));
        // per sub-block bit count (after all iterations)
        pipe_.InitBuffer(blockBitNumBuf_, BLOCK_SIZE * sizeof(int32_t));
        // decode buffer (int32, 4096 elements)
        pipe_.InitBuffer(bufferBuf_, BIG_BLOCK * sizeof(int32_t));
        // raw exponent bytes (uint8, 4096 elements) per block
        pipe_.InitBuffer(expBuf_, BIG_BLOCK * sizeof(uint8_t));
        // mantissa staging (up to 3 * 4096 bytes)
        pipe_.InitBuffer(mantissaTileBuf_, 3U * BIG_BLOCK);
        // stream chunk buffer (uint16, 2048 elements)
        pipe_.InitBuffer(streamBuf_, 2048 * sizeof(uint16_t));
        // output staging (up to 4096 * 4 bytes)
        pipe_.InitBuffer(outputTileBuf_, BIG_BLOCK * 4U);
        // max-bit storage: 16 * 64 = 1024 uint16
        pipe_.InitBuffer(maxBitStore_, 16 * BLOCK_SIZE * sizeof(uint16_t));
        // overflow mask storage: 16 * 64 = 1024 bytes
        pipe_.InitBuffer(ovMaskStore_, 16 * BLOCK_SIZE * sizeof(uint8_t));
    }

    __aicore__ inline void Process()
    {
        // Step 1: histogram → ranking
        ComputeRanking();

        // Step 2: forward-parse the bit-stream
        //   a) Read all 16 max_bit arrays (each 64 uint16) in forward order
        //   b) Compute accumulated block_bit_num for each iteration
        //   c) Record overflow masks per iteration
        ParseBitStream();

        // Step 3: replay buffer in REVERSE to decode
        DecodeRanksReverse();

        // Step 4: reconstruct float values from exponents + mantissa
        ReconstructAllFloats();
    }

private:
    // ---- ranking -----------------------------------------------------------
    __aicore__ inline void ComputeRanking()
    {
        auto h = histBuf_.template Get<int32_t>();
        auto s = sortIdxBuf_.template Get<int32_t>();
        auto r = rankingBuf_.template Get<int32_t>();
        auto v = invRankBuf_.template Get<int32_t>();

        AscendC::DataCopyExtParams cp = {
            1U, HIST_SIZE * sizeof(int32_t), 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<int32_t> pp = {
            true, 0U, 0U, static_cast<int32_t>(0)};
        AscendC::DataCopyPad(h, histGlobal_, cp, pp);
        AscendC::PipeBarrier<PIPE_V>();

        for (int32_t i = 0; i < HIST_SIZE; ++i) s.SetValue(i, i);
        for (int32_t i = 0; i < HIST_SIZE - 1; ++i) {
            for (int32_t j = 0; j < HIST_SIZE - 1 - i; ++j) {
                int32_t i0 = s.GetValue(j);
                int32_t i1 = s.GetValue(j + 1);
                if (h.GetValue(i0) < h.GetValue(i1)) {
                    s.SetValue(j, i1);
                    s.SetValue(j + 1, i0);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();
        for (int32_t k = 0; k < HIST_SIZE; ++k) {
            int32_t eb = s.GetValue(k);
            r.SetValue(eb, k);
            v.SetValue(k, eb);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---- stream helpers ----------------------------------------------------
    __aicore__ inline void LoadU16(AscendC::LocalTensor<uint16_t> &dst,
                                   uint32_t pos, uint32_t cnt)
    {
        auto src = fixedU16Global_[pos];
        AscendC::DataCopyExtParams cp = {
            1U, cnt * static_cast<uint32_t>(sizeof(uint16_t)),
            0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<uint16_t> pp = {
            true, 0U, 0U, static_cast<uint16_t>(0)};
        AscendC::DataCopyPad(dst, src, cp, pp);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---- forward bit-stream parse ------------------------------------------
    __aicore__ inline void ParseBitStream()
    {
        auto ss   = streamBuf_.template Get<uint16_t>();
        auto mb   = maxBitStore_.template Get<uint16_t>();
        auto ovm  = ovMaskStore_.template Get<uint8_t>();
        auto bbn  = blockBitNumBuf_.template Get<int32_t>();

        uint32_t slen = totalFixedF_ * dtypeBytes_ / 2U;
        uint32_t spos = META_SIZE;  // skip meta header

        AscendC::Duplicate(bbn, static_cast<int32_t>(0), BLOCK_SIZE);

        for (uint32_t i = 0U; i < bigLoop_; ++i) {
            // skip any overflow chunks (values > 32 distinguish them from max_bit)
            while (spos + BLOCK_SIZE <= slen) {
                LoadU16(ss, spos, BLOCK_SIZE);
                bool allLe32 = true;
                for (uint32_t j = 0; j < BLOCK_SIZE; ++j) {
                    if (ss.GetValue(j) > 32U) { allLe32 = false; break; }
                }
                if (allLe32) break;   // found max_bit[i]
                spos += BLOCK_SIZE;    // skip overflow chunk
            }

            // read max_bit[i]
            LoadU16(ss, spos, BLOCK_SIZE);
            spos += BLOCK_SIZE;

            // store max_bit and compute overflow mask
            uint32_t base = i * BLOCK_SIZE;
            for (uint32_t j = 0; j < BLOCK_SIZE; ++j) {
                uint16_t val = ss.GetValue(j);
                mb.SetValue(base + j, val);

                int32_t cur = bbn.GetValue(j) + static_cast<int32_t>(val);
                bbn.SetValue(j, cur);

                if (cur > 16) {
                    ovm.SetValue(base + j, static_cast<uint8_t>(1));
                } else {
                    ovm.SetValue(base + j, static_cast<uint8_t>(0));
                }
            }
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Now blockBitNumBuf_ holds the FINAL accumulated bit counts
        // (before any overflow reductions in the encoder).
        // In the encoder, overflow reductions modify block_bit_num,
        // but we only need the overflow mask, which is stored per iteration.
    }

    // ---- reverse decode ranks ----------------------------------------------
    __aicore__ inline void DecodeRanksReverse()
    {
        auto mb     = maxBitStore_.template Get<uint16_t>();
        auto ovm    = ovMaskStore_.template Get<uint8_t>();
        auto invRank = invRankBuf_.template Get<int32_t>();
        auto buffer  = bufferBuf_.template Get<int32_t>();
        auto expL    = expBuf_.template Get<uint8_t>();
        auto ss      = streamBuf_.template Get<uint16_t>();

        // Initialise buffer to zero
        AscendC::Duplicate(buffer, static_cast<int32_t>(0), BIG_BLOCK);

        uint32_t slen = totalFixedF_ * dtypeBytes_ / 2U;

        // Collect per-iteration overflow data positions by forward-pass through stream
        // We re-parse the stream to also extract overflow data values
        // Overflow data positions must be pre-computed from the encoder stream
        // format: per big_loop i, overflow_i precedes max_bit_i+1 in the stream

        // Simplified approach: re-parse forward, maintaining the same scanner
        // This time we also extract overflow data
        uint32_t spos = META_SIZE;
        auto ss2 = streamBuf_.template Get<uint16_t>();

        // Re-read meta to skip
        // LoadU16 already advances, just use it

        // For each iteration, skip past any overflow data, read max_bit, then
        // store the stream position of overflow data
        // Then in the reverse loop, apply overflow to buffer before extracting

        // But we need overflow data per iteration, not just positions.
        // The overflow data for iteration i is in the stream before max_bit[i+1].
        // We need to store overflow values for application during reverse decode.

        // Since overflow size is limited (max 64 * 64 = 4096 uint16 per iter),
        // and we have 256KB UB, let's just re-parse the stream during reverse
        // processing instead of pre-storing everything.

        // Better approach: process reverse using stored max_bit + overflow mask
        // and re-read overflow data from the stream as needed.

        // The key insight: for reverse processing, I need to apply overflow
        // data to the buffer BEFORE extracting ranks. But overflow data for
        // iteration i appears in the stream after max_bit[i] and before max_bit[i+1].

        // In the encoder:
        // iteration i:  [max_bit[i]] [overflow_i (if any)]
        // Wait no... let me re-check.

        // Encoder iteration i:
        // block_bit_num_old + max_bit[i] → if overflow:
        //   outputs.append(overflow_data)  (sum_cmp * 64 uint16)
        //   buffer >>= 16 for overflowing sub-blocks
        //   outputs.append(max_bit[i])     (64 uint16)
        //   block_bit_num[cmp] -= 16
        //
        // So in encoder stream per iteration: [overflow_data?] [max_bit]
        //
        // In decoder (forward parsing):
        // - Read overflow chunks until we find 64 values ≤ 32 → this is max_bit[i]
        // - Overflow chunks preceded max_bit[i]
        //
        // For reverse decode, we need to apply overflow data for iteration i
        // AFTER reading max_bit[i] from the stream (the same position we
        // already stored).
        //
        // Alternative: re-parse forward, counting overflow chunks per iteration.
        // Store overflow count per iteration. Then in reverse, one more pass.

        // Actually, let me just do a two-pass forward + reverse approach:
        // Pass 1 (done in ParseBitStream): read all max_bit, compute ovMask per iteration
        // Pass 2: walk through the stream again, compute overflow counts per iter
        // Pass 3 (reverse): apply overflow data to buffer, extract ranks

        // Let me implement this more carefully with per-iteration overflow info
        // stored in a local array.

        // Overflow count & data for up to 32 iterations (we have 16)
        uint32_t ovCount[32] = {0};
        uint32_t ovStart[32] = {0};

        // Forward pass 2: determine overflow per iteration
        spos = META_SIZE;
        for (uint32_t i = 0U; i < bigLoop_; ++i) {
            // Count overflow chunks before max_bit[i]
            uint32_t ovPos = spos;
            uint32_t ovCnt = 0U;
            while (spos + BLOCK_SIZE <= slen) {
                LoadU16(ss2, spos, BLOCK_SIZE);
                bool allLe32 = true;
                for (uint32_t j = 0; j < BLOCK_SIZE; ++j) {
                    if (ss2.GetValue(j) > 32U) { allLe32 = false; break; }
                }
                if (allLe32) break;
                spos += BLOCK_SIZE;
                ovCnt++;
            }
            ovCount[i] = ovCnt;
            ovStart[i] = ovPos;
            // Skip the max_bit chunk
            spos += BLOCK_SIZE;
        }

        // Reset buffer to zero
        AscendC::Duplicate(buffer, static_cast<int32_t>(0), BIG_BLOCK);

        // Reverse decode: i = bigLoop_-1 down to 0
        for (int32_t i = static_cast<int32_t>(bigLoop_) - 1; i >= 0; --i) {
            uint32_t ui = static_cast<uint32_t>(i);

            // Step A: if this iteration had overflow, apply overflow data
            // overflow_i data precedes max_bit[i] in the stream
            if (ovCount[ui] > 0U) {
                // Count how many sub-blocks actually overflowed at this iteration
                // The overflow chunks in stream match the sub-blocks in
                // ovMask order, but only the True ones
                uint32_t ovChunkIdx = 0U;
                for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
                    uint8_t maskVal = ovm.GetValue(ui * BLOCK_SIZE + sj);
                    if (maskVal) {
                        // Read this sub-block's overflow data
                        uint32_t chunkPos = ovStart[ui] + ovChunkIdx * BLOCK_SIZE;
                        LoadU16(ss2, chunkPos, BLOCK_SIZE);

                        uint32_t eb = sj * BLOCK_SIZE;
                        for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                            int32_t cur = buffer.GetValue(eb + ei);
                            uint16_t ov = ss2.GetValue(ei);
                            // Reverse the encoder's: buffer >> 16, then write low16
                            // Decoder: buffer << 16 | overflow_low16
                            buffer.SetValue(eb + ei,
                                (cur << 16) | static_cast<int32_t>(ov));
                        }
                        ovChunkIdx++;
                    }
                }
                AscendC::PipeBarrier<PIPE_V>();
            }

            // Step B: extract exp_sort_idx from buffer using max_bit[i][j]
            for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
                uint16_t mbv   = mb.GetValue(ui * BLOCK_SIZE + sj);
                uint32_t ebase  = sj * BLOCK_SIZE;

                if (mbv == 0) {
                    int32_t eb = invRank.GetValue(0);
                    uint8_t v  = static_cast<uint8_t>(eb);
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                        expL.SetValue(ebase + ei, v);
                    }
                } else {
                    int32_t mask = (1 << static_cast<int32_t>(mbv)) - 1;
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                        int32_t bv  = buffer.GetValue(ebase + ei);
                        int32_t rk  = bv & mask;
                        int32_t eb  = invRank.GetValue(rk);
                        expL.SetValue(ebase + ei, static_cast<uint8_t>(eb));
                        buffer.SetValue(ebase + ei, bv >> static_cast<int32_t>(mbv));
                    }
                }
            }
            AscendC::PipeBarrier<PIPE_V>();

            // Step C: reconstruct float values for this block
            // expL now contains exponent bytes for this 4096-element block
            ReconstructFloatsBlock(ui, expL);
        }
    }

    // ---- reconstruct one block of floats -----------------------------------
    __aicore__ inline void ReconstructFloatsBlock(
        uint32_t blk,
        AscendC::LocalTensor<uint8_t> &expLocal)
    {
        auto mTile  = mantissaTileBuf_.template Get<uint8_t>();
        auto outTile = outputTileBuf_.template Get<uint8_t>();

        if (dtypeBytes_ == 4U) {
            uint32_t mOff = blk * BIG_BLOCK * 3U;
            auto mSrc = mantissaGlobal_[mOff];
            {
                AscendC::DataCopyExtParams cp = {1U, BIG_BLOCK * 3U, 0U, 0U, 0U};
                AscendC::DataCopyPadExtParams<uint8_t> pp = {
                    true, 0U, 0U, static_cast<uint8_t>(0)};
                AscendC::DataCopyPad(mTile, mSrc, cp, pp);
            }
            AscendC::PipeBarrier<PIPE_V>();

            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                outTile.SetValue(i * 4U + 0U, mTile.GetValue(i * 3U));
                outTile.SetValue(i * 4U + 1U, mTile.GetValue(i * 3U + 1U));
                outTile.SetValue(i * 4U + 2U, mTile.GetValue(i * 3U + 2U));
                outTile.SetValue(i * 4U + 3U, expLocal.GetValue(i));
            }
            AscendC::PipeBarrier<PIPE_V>();

            auto dst = outputGlobal_[blk * BIG_BLOCK * 4U];
            {
                AscendC::DataCopyExtParams cp = {1U, BIG_BLOCK * 4U, 0U, 0U, 0U};
                AscendC::DataCopyPad(dst, outTile, cp);
            }
            AscendC::PipeBarrier<PIPE_V>();
        } else {
            uint32_t mOff = blk * BIG_BLOCK * 1U;
            auto mSrc = mantissaGlobal_[mOff];
            {
                AscendC::DataCopyExtParams cp = {1U, BIG_BLOCK * 1U, 0U, 0U, 0U};
                AscendC::DataCopyPadExtParams<uint8_t> pp = {
                    true, 0U, 0U, static_cast<uint8_t>(0)};
                AscendC::DataCopyPad(mTile, mSrc, cp, pp);
            }
            AscendC::PipeBarrier<PIPE_V>();

            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                outTile.SetValue(i * 2U,     mTile.GetValue(i));
                outTile.SetValue(i * 2U + 1U, expLocal.GetValue(i));
            }
            AscendC::PipeBarrier<PIPE_V>();

            auto dst = outputGlobal_[blk * BIG_BLOCK * 2U];
            {
                AscendC::DataCopyExtParams cp = {1U, BIG_BLOCK * 2U, 0U, 0U, 0U};
                AscendC::DataCopyPad(dst, outTile, cp);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // ---- reconstruct all floats --------------------------------------------
    __aicore__ inline void ReconstructAllFloats()
    {
        // Already done in DecodeRanksReverse; just ensure all writes flushed
        AscendC::PipeBarrier<PIPE_V>();
    }

    // ---- data members ------------------------------------------------------
    AscendC::TPipe pipe_;

    AscendC::GlobalTensor<uint8_t>  outputGlobal_;
    AscendC::GlobalTensor<uint8_t>  inputGlobal_;
    AscendC::GlobalTensor<uint8_t>  mantissaGlobal_;
    AscendC::GlobalTensor<uint16_t> fixedU16Global_;
    AscendC::GlobalTensor<uint8_t>  varGlobal_;
    AscendC::GlobalTensor<int32_t>  histGlobal_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sortIdxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rankingBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> invRankBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> blockBitNumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufferBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> expBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mantissaTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> streamBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outputTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBitStore_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> ovMaskStore_;

    uint32_t totalElems_{0};
    uint32_t totalMantissaF_{0};
    uint32_t totalFixedF_{0};
    uint32_t dtypeBytes_{0};
    uint32_t mantissaBytes_{0};
    uint32_t shiftBits_{0};
    uint32_t bigLoop_{0};
};

