// HansDecode AscendC kernel
//
// Decodes Hans-encoded float data. Algorithm mirrors gen_encode_golden_np
// in reverse. Single-core processing due to sequential bit-stream dependencies.
//
// Bit-stream layout (after meta_info header of 128 uint16):
//   iteration 0:  [overflow_0*] max_bit_0     (0..sum_cmp overflow sub-blocks)
//   iteration 1:  [overflow_1*] max_bit_1
//   ...
//   iteration N-1: [overflow_N-1*] max_bit_N-1
//   final_buffer: 4096 uint16 (low-16 of each buffer element)
//   final_block_bit_num: 128 uint16 (64 int32 values)

#include "kernel_operator.h"

constexpr int32_t BLOCK_SIZE = 64;
constexpr int32_t BIG_BLOCK  = 4096;
constexpr int32_t HIST_SIZE  = 256;
constexpr int32_t META_SIZE  = 128;

class KernelHansDecode {
public:
    __aicore__ inline void Init(
        GM_ADDR oGM, GM_ADDR iGM, GM_ADDR mGM, GM_ADDR fGM, GM_ADDR vGM, GM_ADDR hGM,
        int32_t tN, int32_t tMf, int32_t tFf,
        int32_t dB, int32_t mB, int32_t sB, int32_t rv)
    {
        N     = static_cast<uint32_t>(tN);
        nMF   = static_cast<uint32_t>(tMf);
        nFF   = static_cast<uint32_t>(tFf);
        dB_   = dB;
        sB_   = sB;
        loops_ = N / BIG_BLOCK;

        outputGlobal_.SetGlobalBuffer( reinterpret_cast<__gm__ uint8_t*>(oGM), N * dB);
        inputGlobal_.SetGlobalBuffer(  reinterpret_cast<__gm__ uint8_t*>(iGM), N * dB);
        mantissaGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ uint8_t*>(mGM), nMF * dB);
        varGlobal_.SetGlobalBuffer(    reinterpret_cast<__gm__ uint8_t*>(vGM), nFF * dB);
        histGlobal_.SetGlobalBuffer(   reinterpret_cast<__gm__ int32_t*>(hGM), HIST_SIZE);
        streamGlobal_.SetGlobalBuffer( reinterpret_cast<__gm__ uint16_t*>(fGM), nFF * dB / 2U);

        // -- UB buffers --
        pipe_.InitBuffer(histBuf_,   HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(sortBuf_,   HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(rankBuf_,   HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(invBuf_,    HIST_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(bbnBuf_,    BLOCK_SIZE * sizeof(int32_t));
        pipe_.InitBuffer(bufBuf_,    BIG_BLOCK * sizeof(int32_t));
        pipe_.InitBuffer(expBuf_,    BIG_BLOCK);
        pipe_.InitBuffer(mTileBuf_,  3U * BIG_BLOCK);
        pipe_.InitBuffer(sBuf_,      4096 * sizeof(uint16_t));
        pipe_.InitBuffer(oTileBuf_,  BIG_BLOCK * 4U);
        pipe_.InitBuffer(mbStore_,   loops_ * BLOCK_SIZE * sizeof(uint16_t));
        pipe_.InitBuffer(ovStore_,   loops_ * BLOCK_SIZE);
        pipe_.InitBuffer(ovCntBuf_,  32 * sizeof(int32_t));
        pipe_.InitBuffer(ovPosBuf_,  32 * sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        ComputeRanking();          // hist → sort → ranking → invRank
        ParseStream();             // forward pass: max_bit + overflow counts
        ReverseDecode();           // reverse pass: extract ranks → exponents
        ReconstructAll();          // exponents + mantissa → float → GM
    }

private:
    // =======================================================================
    // ComputeRanking — bubble-sort hist descending, fill invRank
    // =======================================================================
    __aicore__ inline void ComputeRanking()
    {
        auto h = histBuf_.template Get<int32_t>();
        auto s = sortBuf_.template Get<int32_t>();
        auto r = rankBuf_.template Get<int32_t>();
        auto v = invBuf_.template Get<int32_t>();

        AscendC::DataCopyExtParams cp = {1U, HIST_SIZE * sizeof(int32_t), 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<int32_t> pp = {true, 0U, 0U, 0};
        AscendC::DataCopyPad(h, histGlobal_, cp, pp);
        AscendC::PipeBarrier<PIPE_V>();

        for (int32_t i = 0; i < HIST_SIZE; ++i) s.SetValue(i, i);
        for (int32_t i = 0; i < HIST_SIZE - 1; ++i)
            for (int32_t j = 0; j < HIST_SIZE - 1 - i; ++j) {
                int32_t a = s.GetValue(j), b = s.GetValue(j + 1);
                if (h.GetValue(a) < h.GetValue(b)) {
                    s.SetValue(j, b); s.SetValue(j + 1, a);
                }
            }
        AscendC::PipeBarrier<PIPE_V>();
        for (int32_t k = 0; k < HIST_SIZE; ++k) {
            int32_t eb = s.GetValue(k);
            r.SetValue(eb, k);
            v.SetValue(k, eb);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    // =======================================================================
    // stream helpers
    // =======================================================================
    __aicore__ inline void RdU16(AscendC::LocalTensor<uint16_t> &d,
                                  uint32_t p, uint32_t c)
    {
        AscendC::DataCopyExtParams cp = {1U, c << 1U, 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<uint16_t> pp = {true, 0U, 0U, 0};
        AscendC::DataCopyPad(d, streamGlobal_[p], cp, pp);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // =======================================================================
    // ParseStream — forward pass: collect max_bit and overflow info
    // =======================================================================
    __aicore__ inline void ParseStream()
    {
        auto ss   = sBuf_.template Get<uint16_t>();
        auto mb   = mbStore_.template Get<uint16_t>();
        auto ovm  = ovStore_.template Get<uint8_t>();
        auto bbn  = bbnBuf_.template Get<int32_t>();
        auto ovC  = ovCntBuf_.template Get<int32_t>();

        uint32_t slen = nFF * dB_ / 2U;
        uint32_t pos  = META_SIZE;
        AscendC::Duplicate(bbn, 0, BLOCK_SIZE);

        for (uint32_t i = 0U; i < loops_; ++i) {
            uint32_t ovStart = pos;
            int32_t  ovCount = 0;
            // skip overflow chunks until we find max_bit (all values <= 32)
            while (pos + BLOCK_SIZE <= slen) {
                RdU16(ss, pos, BLOCK_SIZE);
                bool ok = true;
                for (uint32_t j = 0; j < BLOCK_SIZE; ++j)
                    if (ss.GetValue(j) > 32U) { ok = false; break; }
                if (ok) break;
                pos += BLOCK_SIZE; ++ovCount;
            }
            ovC.SetValue(i, ovCount);
            ovPosBuf_.Get<int32_t>().SetValue(i, static_cast<int32_t>(ovStart));

            // read max_bit[i]
            RdU16(ss, pos, BLOCK_SIZE);
            pos += BLOCK_SIZE;

            uint32_t base = i * BLOCK_SIZE;
            for (uint32_t j = 0; j < BLOCK_SIZE; ++j) {
                uint16_t m = ss.GetValue(j);
                mb.SetValue(base + j, m);
                int32_t cur = bbn.GetValue(j) + static_cast<int32_t>(m);
                ovm.SetValue(base + j, (cur > 16) ? static_cast<uint8_t>(1)
                                                  : static_cast<uint8_t>(0));
                if (cur > 16) cur -= 16;
                bbn.SetValue(j, cur);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Save final buffer position in stream (pos is after all max_bit arrays)
        finalBufPos_ = pos;
    }

    // =======================================================================
    // ReverseDecode — backward pass on the bit-stream
    // =======================================================================
    __aicore__ inline void ReverseDecode()
    {
        auto ss   = sBuf_.template Get<uint16_t>();
        auto mb   = mbStore_.template Get<uint16_t>();
        auto ovm  = ovStore_.template Get<uint8_t>();
        auto ovC  = ovCntBuf_.template Get<int32_t>();
        auto ovP  = ovPosBuf_.template Get<int32_t>();
        auto inv  = invBuf_.template Get<int32_t>();
        auto buf  = bufBuf_.template Get<int32_t>();
        auto expL = expBuf_.template Get<uint8_t>();

        // --- load final buffer from stream ---
        uint32_t slen = nFF * dB_ / 2U;
        uint32_t pos  = finalBufPos_;
        AscendC::Duplicate(buf, 0, BIG_BLOCK);
        if (pos + BIG_BLOCK <= slen) {
            RdU16(ss, pos, BIG_BLOCK);
            pos += BIG_BLOCK;
            for (uint32_t k = 0U; k < BIG_BLOCK; ++k)
                buf.SetValue(k, static_cast<int32_t>(ss.GetValue(k)));
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Skip final_block_bit_num (64 int32 = 128 uint16)
        // pos += 128;  // not needed, just skip conceptually

        // --- reverse decode ---
        for (int32_t ii = static_cast<int32_t>(loops_) - 1; ii >= 0; --ii) {
            uint32_t i = static_cast<uint32_t>(ii);
            // A) Apply overflow data for this iteration
            int32_t cnt = ovC.GetValue(i);
            uint32_t oStart = static_cast<uint32_t>(ovP.GetValue(i));
            uint32_t subIdx = 0U;
            for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
                if (ovm.GetValue(i * BLOCK_SIZE + sj) == static_cast<uint8_t>(1)) {
                    // Read overflow chunk (64 uint16) for this sub-block
                    RdU16(ss, oStart + subIdx * BLOCK_SIZE, BLOCK_SIZE);
                    uint32_t base = sj * BLOCK_SIZE;
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                        int32_t v = buf.GetValue(base + ei);
                        buf.SetValue(base + ei,
                                     (v << 16) | static_cast<int32_t>(ss.GetValue(ei)));
                    }
                    ++subIdx;
                }
            }
            AscendC::PipeBarrier<PIPE_V>();

            // B) Extract ranks and shift buffer
            for (uint32_t sj = 0U; sj < BLOCK_SIZE; ++sj) {
                uint16_t mv = mb.GetValue(i * BLOCK_SIZE + sj);
                uint32_t base = sj * BLOCK_SIZE;
                if (mv == 0) {
                    int32_t eb = inv.GetValue(0);
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei)
                        expL.SetValue(base + ei, static_cast<uint8_t>(eb));
                } else {
                    int32_t mask = (1 << static_cast<int32_t>(mv)) - 1;
                    for (uint32_t ei = 0U; ei < BLOCK_SIZE; ++ei) {
                        int32_t bv = buf.GetValue(base + ei);
                        int32_t rk = bv & mask;
                        expL.SetValue(base + ei,
                                      static_cast<uint8_t>(inv.GetValue(rk)));
                        buf.SetValue(base + ei, bv >> static_cast<int32_t>(mv));
                    }
                }
            }
            AscendC::PipeBarrier<PIPE_V>();

            // C) Reconstruct float block and write to GM
            WriteBlock(i, expL);
        }
    }

    // =======================================================================
    // WriteBlock — assemble float bytes from exponents + mantissa → GM
    // =======================================================================
    __aicore__ inline void WriteBlock(uint32_t blk,
                                       AscendC::LocalTensor<uint8_t> &expLocal)
    {
        auto m = mTileBuf_.template Get<uint8_t>();
        auto o = oTileBuf_.template Get<uint8_t>();

        if (dB_ == 4) {
            uint32_t off = blk * BIG_BLOCK * 3U;
            AscendC::DataCopyExtParams cp = {1U, BIG_BLOCK * 3U, 0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<uint8_t> pp = {true, 0U, 0U, 0};
            AscendC::DataCopyPad(m, mantissaGlobal_[off], cp, pp);
            AscendC::PipeBarrier<PIPE_V>();
            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                o.SetValue(i * 4U,     m.GetValue(i * 3U));
                o.SetValue(i * 4U + 1, m.GetValue(i * 3U + 1U));
                o.SetValue(i * 4U + 2, m.GetValue(i * 3U + 2U));
                o.SetValue(i * 4U + 3, expLocal.GetValue(i));
            }
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopyPad(outputGlobal_[blk * BIG_BLOCK * 4U], o,
                                 AscendC::DataCopyExtParams{1U, BIG_BLOCK * 4U, 0U, 0U, 0U});
        } else {
            uint32_t off = blk * BIG_BLOCK * 1U;
            AscendC::DataCopyExtParams cp = {1U, BIG_BLOCK * 1U, 0U, 0U, 0U};
            AscendC::DataCopyPadExtParams<uint8_t> pp = {true, 0U, 0U, 0};
            AscendC::DataCopyPad(m, mantissaGlobal_[off], cp, pp);
            AscendC::PipeBarrier<PIPE_V>();
            for (uint32_t i = 0U; i < BIG_BLOCK; ++i) {
                o.SetValue(i * 2U,     m.GetValue(i));
                o.SetValue(i * 2U + 1, expLocal.GetValue(i));
            }
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopyPad(outputGlobal_[blk * BIG_BLOCK * 2U], o,
                                 AscendC::DataCopyExtParams{1U, BIG_BLOCK * 2U, 0U, 0U, 0U});
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ReconstructAll() { AscendC::PipeBarrier<PIPE_V>(); }

    // =======================================================================
    // members
    // =======================================================================
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<uint8_t>  outputGlobal_, inputGlobal_, mantissaGlobal_, varGlobal_;
    AscendC::GlobalTensor<int32_t>  histGlobal_;
    AscendC::GlobalTensor<uint16_t> streamGlobal_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> histBuf_, sortBuf_, rankBuf_, invBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bbnBuf_, bufBuf_, expBuf_, mTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sBuf_, oTileBuf_, mbStore_, ovStore_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> ovCntBuf_, ovPosBuf_;

    uint32_t N{0}, nMF{0}, nFF{0};
    int32_t  dB_{0}, sB_{0};
    uint32_t loops_{0}, finalBufPos_{0};
};

extern "C" __global__ __aicore__ void hans_decode(
    GM_ADDR o, GM_ADDR i, GM_ADDR m, GM_ADDR f, GM_ADDR v, GM_ADDR h,
    int32_t N, int32_t M, int32_t F, int32_t dB, int32_t mB, int32_t sB, int32_t rv)
{
    KernelHansDecode k;
    k.Init(o, i, m, f, v, h, N, M, F, dB, mB, sB, rv);
    k.Process();
}
