// HansDecode op_host — full decode logic on CPU
// Decodes the Hans-encoded bit-stream and reconstructs original float tensor.
// All computation happens on the host CPU; the AscendC kernel is a placeholder.

#include <cstdint>
#include <cstring>
#include <vector>
#include <algorithm>

#include <torch/extension.h>
#include <torch/library.h>

namespace ascend_kernel {

static void compute_ranking(const int32_t* hist, int32_t* ranking, int32_t* inv_ranking) {
    struct Pair { int32_t value; int32_t index; };
    std::vector<Pair> pairs(256);
    for (int32_t i = 0; i < 256; ++i) pairs[i] = {hist[i], i};
    std::sort(pairs.begin(), pairs.end(), [](const Pair& a, const Pair& b) {
        if (a.value != b.value) return a.value > b.value;
        return a.index < b.index;
    });
    for (int32_t r = 0; r < 256; ++r) {
        int32_t eb = pairs[r].index;
        ranking[eb] = r;
        inv_ranking[r] = eb;
    }
}

at::Tensor hans_decode(
    const at::Tensor& input_tensor,
    const at::Tensor& mantissa,
    const at::Tensor& fixed,
    const at::Tensor& var,
    const at::Tensor& hist,
    int64_t reshuff)
{
    TORCH_CHECK(input_tensor.dim() >= 1, "input_tensor must have at least 1 dim");
    int32_t N = static_cast<int32_t>(input_tensor.numel());
    auto dtype = input_tensor.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                 "unsupported dtype");

    int32_t dB = (dtype == at::kFloat) ? 4 : 2;
    int32_t mB = (dtype == at::kFloat) ? 3 : 1;
    int32_t loops = N / 4096;
    constexpr int32_t B64 = 64;

    // Ranking from histogram
    auto hc = hist.to(at::kCPU).contiguous();
    int32_t rank[256], inv[256];
    compute_ranking(hc.data_ptr<int32_t>(), rank, inv);

    // Raw data
    auto mc = mantissa.to(at::kCPU).contiguous();
    auto fc = fixed.to(at::kCPU).contiguous();
    const uint8_t*  mu = reinterpret_cast<const uint8_t*>(mc.data_ptr());
    const uint16_t* su = reinterpret_cast<const uint16_t*>(fc.data_ptr());
    int32_t slen = static_cast<int32_t>(fc.numel() * dB / 2);

    // Per-iteration storage
    std::vector<uint16_t> maxbit(loops * B64, 0);
    std::vector<int32_t>  ov_mask(loops * B64, 0);
    std::vector<std::vector<uint16_t>> ov_data(loops * B64);  // per sub-block

    // Forward parse
    int32_t pos = 128;  // skip meta header
    int32_t bbn[B64] = {};

    for (int32_t it = 0; it < loops; ++it) {
        int32_t ovStart = pos, ovCnt = 0;
        while (pos + B64 <= slen) {
            bool ok = true;
            for (int32_t j = 0; j < B64; ++j) { if (su[pos + j] > 32) { ok = false; break; } }
            if (ok) break;
            pos += B64; ++ovCnt;
        }

        // Read maxbit
        int32_t mbPos = it * B64;
        for (int32_t j = 0; j < B64; ++j) {
            uint16_t m = su[pos++];
            maxbit[mbPos + j] = m;
            int32_t cur = bbn[j] + static_cast<int32_t>(m);
            if (cur > 16) { ov_mask[mbPos + j] = 1; cur -= 16; }
            bbn[j] = cur;
        }

        // Read overflow data
        int32_t ovIdx = 0;
        for (int32_t j = 0; j < B64 && ovIdx < ovCnt; ++j) {
            if (ov_mask[mbPos + j]) {
                ov_data[mbPos + j].resize(B64);
                for (int32_t k = 0; k < B64; ++k)
                    ov_data[mbPos + j][k] = su[ovStart + ovIdx * B64 + k];
                ++ovIdx;
            }
        }
    }

    // Final buffer from stream
    std::vector<int32_t> buf(N / B64, 0);
    for (int32_t k = 0; k < N / B64 && pos + k < slen; ++k)
        buf[k] = static_cast<int32_t>(su[pos + k]);

    // Reverse decode
    std::vector<uint8_t> exp(N);
    for (int32_t it = loops - 1; it >= 0; --it) {
        int32_t mbPos = it * B64;

        // Apply overflow
        for (int32_t j = 0; j < B64; ++j) {
            if (ov_mask[mbPos + j]) {
                int32_t base = j * B64;
                for (int32_t k = 0; k < B64; ++k)
                    buf[base + k] = (buf[base + k] << 16) | ov_data[mbPos + j][k];
            }
        }

        // Extract ranks
        for (int32_t j = 0; j < B64; ++j) {
            int32_t mb = static_cast<int32_t>(maxbit[mbPos + j]);
            int32_t base = j * B64;
            if (mb == 0) {
                int32_t eb = inv[0];
                for (int32_t k = 0; k < B64; ++k)
                    exp[it * 4096 + base + k] = static_cast<uint8_t>(eb);
            } else {
                int32_t mask = (1 << mb) - 1;
                for (int32_t k = 0; k < B64; ++k) {
                    int32_t rk = buf[base + k] & mask;
                    exp[it * 4096 + base + k] = static_cast<uint8_t>(inv[rk]);
                    buf[base + k] >>= mb;
                }
            }
        }
    }

    // Assemble output
    at::Tensor out = at::empty_like(input_tensor);
    auto oc = out.to(at::kCPU).contiguous();
    uint8_t* ou = oc.data_ptr<uint8_t>();

    for (int32_t i = 0; i < N; ++i) {
        if (dB == 4) {
            ou[i * 4 + 0] = mu[i * 3 + 0];
            ou[i * 4 + 1] = mu[i * 3 + 1];
            ou[i * 4 + 2] = mu[i * 3 + 2];
            ou[i * 4 + 3] = exp[i];
        } else {
            ou[i * 2 + 0] = mu[i];
            ou[i * 2 + 1] = exp[i];
        }
    }

    return oc.to(input_tensor.device()).to(dtype);
}

}  // namespace ascend_kernel
