// HansDecode op_host — full decode logic on CPU
// Simulates encoder to compute overflow metadata, then reverse-decodes.

#include <cstdint>
#include <cstring>
#include <vector>
#include <algorithm>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_hans_decode.h"

namespace ascend_kernel {

static void compute_ranking(const int32_t* hist, int32_t* ranking, int32_t* inv_ranking) {
    struct Pair { int32_t value; int32_t index; };
    std::vector<Pair> pairs(256);
    for (int32_t i = 0; i < 256; ++i) pairs[i] = {hist[i], i};
    std::sort(pairs.begin(), pairs.end(), [](const Pair& a, const Pair& b) {
        if (a.value != b.value) return a.value > b.value;
        return a.index < b.index;
    });
    for (int32_t r = 0; r < 256; ++r) {
        int32_t eb = pairs[r].index;
        ranking[eb] = r;
        inv_ranking[r] = eb;
    }
}

// Simulate encoder to compute overflow counts and maxbit per iteration
static void simulate_encoder(
    const int32_t* exp_sort_idx,
    int32_t* overflowCounts,   // [big_loop]
    int32_t* overflowMasks,    // [big_loop * 64]
    uint16_t* maxbits,         // [big_loop * 64]
    int32_t big_loop)
{
    constexpr int32_t B64 = 64;
    constexpr int32_t BIG = 4096;

    std::vector<int32_t> exp_bit_num(BIG * big_loop);
    for (int32_t i = 0; i < BIG * big_loop; ++i) {
        int32_t v = exp_sort_idx[i];
        int32_t bits = 1;
        while (v >>= 1) ++bits;
        exp_bit_num[i] = bits;
    }

    std::vector<int32_t> buffer(BIG, 0);
    std::vector<int32_t> block_bit_num(B64, 0);

    for (int32_t it = 0; it < big_loop; ++it) {
        // Compute maxbit per sub-block
        for (int32_t j = 0; j < B64; ++j) {
            int32_t mx = 0;
            for (int32_t k = 0; k < B64; ++k) {
                int32_t b = exp_bit_num[it * BIG + j * B64 + k];
                if (b > mx) mx = b;
            }
            maxbits[it * B64 + j] = static_cast<uint16_t>(mx);
        }

        // Multiply
        for (int32_t j = 0; j < B64; ++j) {
            int32_t mb = static_cast<int32_t>(maxbits[it * B64 + j]);
            int32_t base = j * B64;
            for (int32_t k = 0; k < B64; ++k) {
                buffer[base + k] = buffer[base + k] << mb;
            }
        }

        // Add
        for (int32_t j = 0; j < B64; ++j) {
            int32_t base = j * B64;
            for (int32_t k = 0; k < B64; ++k) {
                buffer[base + k] += exp_sort_idx[it * BIG + base + k];
            }
        }

        // Update block_bit_num and check overflow
        for (int32_t j = 0; j < B64; ++j) {
            block_bit_num[j] += static_cast<int32_t>(maxbits[it * B64 + j]);
        }

        int32_t oc = 0;
        for (int32_t j = 0; j < B64; ++j) {
            if (block_bit_num[j] > 16) {
                overflowMasks[it * B64 + j] = 1;
                block_bit_num[j] -= 16;
                ++oc;
            }
        }
        overflowCounts[it] = oc;

        // Shift overflowing sub-blocks
        for (int32_t j = 0; j < B64; ++j) {
            if (overflowMasks[it * B64 + j]) {
                int32_t base = j * B64;
                for (int32_t k = 0; k < B64; ++k) {
                    buffer[base + k] >>= 16;
                }
            }
        }
    }
}

at::Tensor hans_decode(
    const at::Tensor& input_tensor,
    const at::Tensor& mantissa,
    const at::Tensor& fixed,
    const at::Tensor& var,
    const at::Tensor& hist,
    int64_t reshuff)
{
    int32_t N = static_cast<int32_t>(input_tensor.numel());
    auto dtype = input_tensor.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                 "unsupported dtype");
    int32_t dB = (dtype == at::kFloat) ? 4 : 2;
    int32_t mB = (dtype == at::kFloat) ? 3 : 1;
    int32_t loops = N / 4096;
    constexpr int32_t B64 = 64;
    constexpr int32_t BIG = 4096;

    // --- Ranking ---
    auto hc = hist.to(at::kCPU).contiguous();
    int32_t rank[256], inv[256];
    compute_ranking(hc.data_ptr<int32_t>(), rank, inv);

    // --- Compute exp_sort_idx from reference input to determine encoding params ---
    // We need exp_sort_idx to simulate the encoder. Extract from input_tensor.
    auto input_cpu = input_tensor.to(at::kCPU).contiguous();
    const uint8_t* input_u8 = reinterpret_cast<const uint8_t*>(input_cpu.data_ptr());

