    for (int32_t i = 0; i < N; ++i) {
        if (dB == 4) {
            exp_array[i] = static_cast<int32_t>(input_u8[i * 4 + 3]);
        } else {
            exp_array[i] = static_cast<int32_t>(input_u8[i * 2 + 1]);
        }
    }

