    std::vector<int32_t> ovCounts(loops, 0);
    std::vector<int32_t> ovMasks(loops * B64, 0);
    std::vector<uint16_t> maxbits(loops * B64, 0);

    simulate_encoder(exp_sort_idx.data(), ovCounts.data(),
