    std::vector<std::vector<uint16_t>> parsedOv(loops);
    std::vector<std::vector<uint16_t>> parsedMaxbits(loops);

    int32_t pos = 128;  // skip meta header
    for (int32_t it = 0; it < loops; ++it) {
        int32_t oc = ovCounts[it];
        parsedOv[it].resize(oc * B64);
        for (int32_t c = 0; c < oc; ++c) {
            for (int32_t k = 0; k < B64; ++k)
                parsedOv[it][c * B64 + k] = su[pos++];
        }
        parsedMaxbits[it].resize(B64);
        for (int32_t k = 0; k < B64; ++k)
            parsedMaxbits[it][k] = su[pos++];
    }

