    std::vector<int32_t> buf(BIG, 0);
    for (int32_t k = 0; k < BIG; ++k)
        buf[k] = static_cast<int32_t>(su[pos++]);

    // --- Reverse decode ---
    std::vector<uint8_t> exp(N);

    for (int32_t it = loops - 1; it >= 0; --it) {
        // Apply overflow
        int32_t chunkIdx = 0;
        for (int32_t j = 0; j < B64; ++j) {
            if (ovMasks[it * B64 + j]) {
                int32_t base = j * B64;
                for (int32_t k = 0; k < B64; ++k) {
                    int32_t ov = static_cast<int32_t>(parsedOv[it][chunkIdx * B64 + k]);
