                    exp[it * BIG + base + k] = static_cast<uint8_t>(inv[0]);
            } else {
                int32_t mask = (1 << mb) - 1;
                for (int32_t k = 0; k < B64; ++k) {
                    int32_t rk = buf[base + k] & mask;
                    exp[it * BIG + base + k] = static_cast<uint8_t>(inv[rk]);
                    buf[base + k] >>= mb;
                }
            }
        }
    }

